import { useState } from 'react'



export function LoadingProgress({ikot}) {

    return (
        ikot && (
            <div className="relative z-10">
        <div
          transition
          className="fixed inset-0 bg-gray-700 bg-opacity-50 transition-opacity data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in"
        />
  
        <div className="fixed inset-0 z-10 w-screen overflow-y-auto">
          <div className="flex min-h-full items-end justify-center p-4 text-center sm:items-center sm:p-0">
            <div
              transition
              className="relative transform overflow-hidden rounded-lg bg-white text-left shadow-xl transition-all data-[closed]:translate-y-4 data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in sm:my-8 w-auto data-[closed]:sm:translate-y-0 data-[closed]:sm:scale-95"
            >
              <div className="bg-white px-4 pb-4 pt-5 sm:p-6 sm:pb-4">
                <div className="flex justify-center items-center">
                  <div>
                    <div className='h-14 w-14 animate-spin border-4 border-t-transparent border-red-500 rounded-full'></div>
                    <div>
                       
                    </div>
                  </div>
                </div>
              </div>
     
            </div>
          </div>
        </div>
      </div>
        
        )
    )
  }


