import axios from "axios";
import React, { useEffect, useState } from "react";
import {
  Button1,
  ButtonAdd,
  ButtonWithIcon,
  LoadingButton,
} from "../components/button";
import {
  ArrowLeftBig,
  BurgerIcon,
  CloseIcon,
  ImageIcon,
  NextIcon,
  PrevIcon,
  SettingsIcon,
  StarIcon,
} from "../components/icons";
import { Loader } from "../components/loader";
import { BigGreetingsTitle } from "../components/title";
import { Toast2 } from "../components/toast";
import { Tooltip5 } from "../components/tooltip";

const LoadPartners = ({ ManageStore, openStore }) => {
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const [currentItems, setCurrentItems] = useState([]);
  // const allpartners = NearbyStore();
  const [allpartners, setPartners] = useState([]);
  useEffect(() => {
    const fetchPartners = async () => {
      try {
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/rider/pullrider/",
          {
            access: null,
          }
        );

        const alldata = response.data;

        if (alldata.status === "success") {
          // setPartners(alldata.users);
          console.log("riders: ", alldata.data);
          // Apply pagination logic
          const indexOfLastItem = currentPage * itemsPerPage;
          const indexOfFirstItem = indexOfLastItem - itemsPerPage;
          const paginatedItems = alldata.data.slice(
            indexOfFirstItem,
            indexOfLastItem
          );

          setCurrentItems(paginatedItems);
          setPartners(paginatedItems);
        }
      } catch (e) {
        console.log(e);
      }
    };

    fetchPartners();
  }, [setPartners, currentPage]);

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  const filteredPartners = allpartners.filter((partner) =>
    partner.FirstName.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const formatMoney = (amount) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "PHP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  const [decryptedBalances, setDecryptedBalances] = useState({});

  const checkPasswordX = async (riderID, passX) => {
    try {
      const response = await axios.post("https://kiefers-app.com/token/", {
        private: 1,
        secret: passX,
      });

      //console.log(response.data);
      if (response.data.status === "ok") {
        setDecryptedBalances((prevState) => ({
          ...prevState,
          [riderID]: formatMoney(response.data.message),
        }));
      }
    } catch (e) {
      console.log(e);
    }
  };

  return (
    <div>
      <div className="absolute top-2 left-14 right-3 max-w-80 sm:top-6 sm:w-80 sm:left-28">
        <input
          type="text"
          placeholder="Search rider..."
          value={searchQuery}
          onChange={handleSearchChange}
          className="p-2 border rounded-xl w-full outline-none"
        />
      </div>
      <section className="rounded-t-xl max-h-[85vh] bg-white overflow-x-auto w-full">
        <table className="rounded-t-xl table-auto border-collapse whitespace-nowrap w-full ">
          <thead className="w-full sticky top-0 bg-[#ff1616] p-4 rounded-t-xl border dark:border-gray-700 z-50">
            <tr className="leading-none  z-50 snap-center p-4">
              <th className="text-white text-center relative p-2.5 font-normal">
                Profile
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Full Name
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Ratings
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                TGID
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Status
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Wallet
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Contact Number
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Rider ID
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Manage
              </th>
            </tr>
          </thead>
          <tbody className="bg-white">
            {filteredPartners.map((store) => (
              <tr
                className="hover:bg-red-50 border border-gray-300"
                key={store.RiderID}
              >
                <td className="w-48 flex justify-center items-center p-2">
                  <img
                    src={store.Profile}
                    alt=""
                    className="transform hover:scale-150 w-auto h-12 rounded-xl object-cover"
                  />
                </td>
                <td className="text-center">{store.FirstName}</td>
                <td className=" text-center">
                  <div className="flex justify-center items-center space-x-2">
                    <StarIcon c="#f59e0b" h="15" w="15" />
                    <p className="mx-0.5">{store.IP_Add}</p>
                  </div>
                </td>

                <td className="text-left">
                  <p className="px-2.5">{store.Email}</p>
                </td>
                <td className="text-center">
                  <div
                    className={`${
                      store.Status === "Active"
                        ? "bg-green-500 text-white"
                        : "bg-slate-200"
                    } px-2 py-0.5 mx-2.5 rounded-lg `}
                  >
                    {store.Status}
                  </div>
                </td>
                <td className=" mx-8 px-2.5">
                  <Tooltip5 text="Click to decrypt the balance.">
                    <button
                      className="w-48 truncate font-mono text-center"
                      onClick={() =>
                        checkPasswordX(store.RiderID, store.Wallet)
                      }
                    >
                      {decryptedBalances[store.RiderID] || store.Wallet}
                    </button>
                  </Tooltip5>
                </td>
                <td className="text-center px-4">{store.Device}</td>
                <td className="text-center px-4">{store.Username}</td>
                <td className="text-center px-6">
                  <ButtonWithIcon
                    press={() => ManageStore(store)}
                    children={<SettingsIcon c="#dc2626" w="18" h="18" />}
                    title="Manage"
                  />
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {allpartners.length === 0 && (
          <div className="h-96 flex justify-center items-center p-8 w-full">
            <Loader />
          </div>
        )}
      </section>

      {filteredPartners.length > 0 && (
        <div className={`flex justify-start p-4 items-center space-x-2`}>
          <button
            className={`${
              currentPage === 1 ? "bg-gray-300" : "bg-red-500"
            } text-white rounded-lg px-2.5 py-2`}
            onClick={() => handlePageChange(currentPage - 1)}
            disabled={currentPage === 1}
          >
            <PrevIcon c="#f1f1f1" w="20" h="20" />
          </button>
          <div className="border border-gray-300 rounded-lg px-2.5 py-2 text-gray-500">
            {currentPage}
          </div>
          <button
            className={`${
              currentItems.length < itemsPerPage ? "bg-gray-300" : "bg-red-500"
            } text-white rounded-lg px-2.5 py-2`}
            onClick={() => handlePageChange(currentPage + 1)}
            disabled={currentItems.length < itemsPerPage}
          >
            <NextIcon c="#f1f1f1" w="20" h="20" />
          </button>
        </div>
      )}
    </div>
  );
};

const CreateMerchant = ({ HereMerchant, private_Date }) => {
  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setTimeout(() => {
      setShow("hidden");
    }, 5000);
  };

  if (HereMerchant === null) {
    var HereMerchant = [];
  }
  console.log("rider: ", HereMerchant);
  const [formData, setFormData] = useState({
    username: HereMerchant.FirstName || "",
    file: HereMerchant.Profile || null,
    telegram: HereMerchant.Email || "",
    phone: HereMerchant.M_Number || "",
    ratings: HereMerchant.IP_Add || "3.0",
    status: HereMerchant.Status || "Inactive",
    schedule: HereMerchant.Schedule || "",
    wallet: HereMerchant.Wallet || "0",
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData({
      ...formData,
      [name]: type === "checkbox" ? checked : value,
    });
  };

  //====UPLOADING FILE
  const [cover, setCover] = useState(HereMerchant.Profile || null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const handleFileChange = (e) => {
    const file = e.target.files[0];

    setFormData({
      ...formData,
      file: file,
    });
    setCover(URL.createObjectURL(file));
    UploadImage(file);
  };

  const [period, setPeriod] = useState("AM");
  const [period2, setPeriod2] = useState("PM");

  const handleTimeChange2 = (e) => {
    const time = e.target.value;
    setFormData({
      ...formData,
      closeTime: `${time} ${period2}`, // Combine time with period
    });
  };

  const formatMoney = (amount) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "PHP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  const [topupamount, setTopUpAmount] = useState(0);
  const [encheck, setEncheck] = useState(false);
  const checkBalance = async (passX) => {
    if (encheck) {
      return;
    }

    try {
      const response = await axios.post("https://kiefers-app.com/token/", {
        private: 1,
        secret: passX,
      });

      //console.log(response.data);
      if (response.data.status === "ok") {
        setFormData((prevState) => ({
          ...prevState,
          wallet: formatMoney(response.data.message),
        }));
        setEncheck(true);
      }
    } catch (e) {
      console.log(e);
    }
  };

  const handleTimeChange = (e) => {
    const time = e.target.value;
    setFormData({
      ...formData,
      openTime: `${time} ${period}`, // Combine time with period
    });
  };

  const handlePeriodChange = (e) => {
    const newPeriod = e.target.value;
    setPeriod(newPeriod);
    setFormData({
      ...formData,
      openTime: `${formData.openTime.split(" ")[0]} ${newPeriod}`, // Combine time with new period
    });
  };

  const handlePeriodChange2 = (e) => {
    const newPeriod = e.target.value;
    setPeriod2(newPeriod);
    setFormData({
      ...formData,
      closeTime: `${formData.openTime.split(" ")[0]} ${newPeriod}`, // Combine time with new period
    });
  };

  const UploadImage = async (file) => {
    const data = new FormData();
    data.append("file", file);

    try {
      const response = await axios.post(
        "https://kiapifers-dlver.cloud/storage/",
        data,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
          onUploadProgress: (progressEvent) => {
            const percentCompleted = Math.round(
              (progressEvent.loaded * 100) / progressEvent.total
            );
            setUploadProgress(percentCompleted);
          },
        }
      );

      if (response.data.success) {
        setUploadProgress(0); // Reset progress after success
        setCover(response.data.url);
      } else {
        showAlert("Error: " + response.data.error);
        setUploadProgress(0); // Reset progress after error
        setCover(null);
      }
    } catch (error) {
      console.error("There was an error uploading the file!", error);
      setUploadProgress(0); // Reset progress after error
      setCover(null);
    }
  };

  const resetImage = () => {
    setCover(null);
  };

  const validate = () => {
    const newErrors = {};

    if (!formData.username) newErrors.username = "Full name is required";
    if (!formData.telegram) newErrors.telegram = "Telegram ID is required";
    if (!formData.ratings) newErrors.ratings = "Ratings is required";
    if (!formData.phone) newErrors.phone = "Phone number is required";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const [loading, setLoading] = useState(false);
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    const data = new FormData();
    for (const key in formData) {
      data.append(key, formData[key]);
    }

    try {
      setLoading(true);

      var boday = {
        FirstName: formData.username,
        LastName: formData.username,
        Username: formData.telegram,
        Profile: cover,
        M_Number: formData.phone,
        Email: formData.telegram,
        Status: formData.status,
        IP_Add: formData.ratings,
        Device: formData.phone,
        Schedule: formData.schedule,
      };
      var api = "https://kiapifers-dlver.cloud/rider/updaterider/";
      if (HereMerchant === null || HereMerchant.length === 0) {
        api = "https://kiapifers-dlver.cloud/rider/create/";
        boday = {
          FirstName: formData.username,
          LastName: formData.username,
          Username: formData.telegram,
          Profile: cover,
          M_Number: formData.phone,
          Email: formData.telegram,
          Status: formData.status,
          Address: "123 Main St, Anytown, USA",
          IP_Add: formData.ratings,
          Device: formData.phone,
          Referral: "referral_code",
          Wallet: "0",
          Extra1: "extra_value1",
          Extra2: "extra_value2",
          Schedule: formData.schedule,
        };
      }

      const response = await axios.post(api, boday, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      console.log(response.data);
      setLoading(false);
      showAlert(
        HereMerchant === null || HereMerchant.length === 0
          ? "Successfully Added!"
          : "Updated!"
      );
    } catch (error) {
      console.error(error);
      showAlert("Please try again. Error!");
      setLoading(false);
    }
  };

  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const handleStartDateChange = (e) => {
    setStartDate(e.target.value);
    serreporLink(null);

    // Optionally, you can reset end date if it is earlier than start date
    if (endDate && e.target.value > endDate) {
      setEndDate("");
    }
  };

  const handleEndDateChange = (e) => {
    setEndDate(e.target.value);
    serreporLink(null);
  };

  const [gene, setGene] = useState(false);
  const [reportlink, serreporLink] = useState(null);
  // Function to convert Date string to Unix Timestamp
  const toUnixTimestamp = (dateStr) =>
    Math.floor(new Date(dateStr).getTime() / 1000);

  const generateReport = async () => {
    // Convert the selected dates to Unix timestamps
    const StartingDate = toUnixTimestamp(startDate);
    const EndDate = toUnixTimestamp(endDate);
    const RiderID = HereMerchant.Username;

    try {
      const response = await axios.get(
        `https://kiapifers-dlver.cloud/report/211df21df/index.php?riderID=${RiderID}&startingDate=${StartingDate}&endDate=${EndDate}`
      );

      setGene(false);
      const maluma = response.data;
      if (maluma.success) {
        serreporLink(maluma.url);
      }
    } catch (e) {
      console.log("error");
      setGene(false);
    }
  };

  const downloadFile = () => {
    if (!reportlink) return;

    console.log(reportlink);

    // Create a temporary <a> element and trigger a download
    const link = document.createElement("a");
    link.href = reportlink;

    // Optionally set a download attribute with a filename
    link.download = reportlink.split("/").pop(); // Use the filename from the URL
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    serreporLink(null);
  };

  const [toloading, settoploading] = useState(false);
  //load rider
  const loadMeRider = async () => {
    if (!topupamount) {
      return;
    }
    settoploading(true);
    try {
      const response = await axios.get(
        `https://kiapifers-dlver.cloud/tg/payment.php?id=${formData.telegram}&amount=${topupamount}`
      );
      console.log(response.data);
      setTopUpAmount("");
      showAlert("Top-up processed");
      settoploading(false);
    } catch (e) {
      setTopUpAmount("");
      showAlert("Top-up processed");
      settoploading(false);
    }
  };

  function cleanAndParseJSON(jString) {
    try {
      // Remove the backslashes by replacing \\" with "
      const cleanedString = jString.replace(/\\"/g, '"');

      // Now parse the cleaned string as JSON
      const parsedData = JSON.parse(cleanedString);

      return parsedData;
    } catch (error) {
      console.error("Failed to clean and parse JSON:", error);
      return null;
    }
  }

  const days = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];
  const [timeSchedule, setSchedule] = useState(
    days.map(() => ({
      openTime: "",
      openPeriod: "AM",
      closeTime: "",
      closePeriod: "PM",
    }))
  );

  const handleSchedTimeChange = (index, field, value) => {
    const newSchedule = [...schedule];
    newSchedule[index][field] = value;
    setSchedule(newSchedule);
  };

  useEffect(() => {
    // If the string has extra escaping, decode it
    let jsonString = cleanAndParseJSON(HereMerchant.Schedule) || null;

    if (jsonString === null) {
      return;
    }

    setSchedule(
      jsonString.map((item) => ({
        day: item.day,
        openTime: item.open.split(" ")[0],
        openPeriod: item.open.split(" ")[1] || "AM",
        closeTime: item.close.split(" ")[0],
        closePeriod: item.close.split(" ")[1] || "PM",
      }))
    );
  }, []);

  const saveSchedule = () => {
    const formattedSchedule = timeSchedule.map((day, index) => ({
      day: days[index],
      open: `${day.openTime} ${day.openPeriod}`,
      close: `${day.closeTime} ${day.closePeriod}`,
    }));
    return formattedSchedule;
    // Save the schedule array to a database or state management solution
  };

  const [startingOpen, setStartingOpen] = useState(HereMerchant.Open || "");
  const [startingClose, setStartingClose] = useState(HereMerchant.Close || "");

  const applyStarting = (e) => {
    setStartingOpen(e.target.value);
    setFormData({
      ...formData,
      openTime: e.target.value,
    });
    setSchedule(
      days.map(() => ({
        openTime: e.target.value,
        openPeriod: "AM",
        closeTime: startingClose,
        closePeriod: "PM",
      }))
    );
  };

  const applyClosing = (e) => {
    setStartingClose(e.target.value);
    setFormData({
      ...formData,
      closeTime: e.target.value,
    });
    setSchedule(
      days.map(() => ({
        openTime: startingOpen,
        openPeriod: "AM",
        closeTime: e.target.value,
        closePeriod: "PM",
      }))
    );
  };

  return (
    <form className="px-2.5" onSubmit={handleSubmit}>
      <div className="space-y-12">
        <div className="border-b border-gray-900/10 pb-12">
          <h2 className="text-base font-semibold leading-7 text-gray-900">
            Personal Information
          </h2>
          <p className="mt-1 text-sm leading-6 text-gray-600">
            This information needs an{" "}
            <span className="text-red-500 font-medium">internal review</span>.
          </p>

          <div className="mt-10 grid grid-cols-1 gap-x-6 gap-y-8 sm:grid-cols-6">
            <div className="sm:col-span-2">
              <label
                htmlFor="file-upload"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Profile Picture
              </label>
              {cover ? (
                <div>
                  <div className="border border-gray-300 rounded-lg w-80 relative">
                    <img
                      src={cover}
                      alt="loading"
                      className="object-cover h-56 w-80 rounded-lg"
                    />
                    <div
                      onClick={resetImage}
                      className="rounded-full shadow-xl cursor-pointer transform scale-100 hover:scale-150 bg-white border border-gray-300 absolute -top-2 -right-2"
                    >
                      <CloseIcon c="#404040" w="20" h="20" />
                    </div>

                    {uploadProgress > 0 && (
                      <div className="flex justify-center items-center inset-0 absolute rounded-lg bg-white bg-opacity-50  w-full h-56">
                        <div>
                          <div className="text-gray-800">
                            Uploading: {uploadProgress}%
                          </div>
                          <div
                            style={{ width: "100%", backgroundColor: "#fff" }}
                          >
                            <div
                              style={{
                                width: `${uploadProgress}%`,
                                backgroundColor: "#ef4444",
                                height: "10px",
                              }}
                            ></div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ) : (
                <div className="mt-2 flex justify-center rounded-lg border border-dashed border-gray-900/25 px-6 py-10">
                  <div className="text-center">
                    <div className="flex justify-center items-center w-full">
                      <ImageIcon c="#404040" w={20} h={20} />
                    </div>
                    <div className="mt-4 flex text-sm leading-6 text-gray-600">
                      <label
                        htmlFor="file-upload"
                        className="relative cursor-pointer rounded-md bg-white font-semibold text-yellow-600  hover:text-red-500"
                      >
                        <span>Upload a file</span>
                        <input
                          id="file-upload"
                          name="file-upload"
                          type="file"
                          className="sr-only outline-none cursor-pointer"
                          onChange={handleFileChange}
                        />
                      </label>
                      <p className="pl-1">or drag and drop</p>
                    </div>
                    <p className="text-xs leading-5 text-gray-600">
                      PNG, JPG up to 5MB and must be 626 x 418
                    </p>
                  </div>
                </div>
              )}
            </div>

            <div className="sm:col-span-3">
              <label
                htmlFor="username"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Riders Legal Name
              </label>
              <div className="mt-2">
                <div className="flex rounded-md shadow-sm ring-1 ring-inset ring-gray-300 outline-none sm:max-w-md">
                  <span className="flex select-none items-center pl-3 text-gray-500 sm:text-sm">
                    kiefers-app.com/
                  </span>
                  <input
                    id="username"
                    name="username"
                    type="text"
                    placeholder="Juan Dela Cruz"
                    autoComplete="username"
                    maxLength={100}
                    className="block flex-1 border-0 bg-transparent outline-none py-1.5 pl-1 text-gray-900 placeholder:text-gray-400 sm:text-sm sm:leading-6"
                    value={formData.username}
                    onChange={handleChange}
                  />
                </div>
                {errors.username && (
                  <p className="text-red-500 text-sm">{errors.username}</p>
                )}
              </div>

              <div className="sm:col-span-3 mt-4">
                <label
                  htmlFor="schedule"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Shift Schedule
                </label>
                <div className="mt-2">
                  <select
                    id="schedule"
                    name="schedule"
                    className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                    value={formData.schedule}
                    onChange={handleChange}
                  >
                    <option value="S1">Shift 1 - 7AM-7PM</option>
                    <option value="S2">Shift 2 - 8AM-8PM</option>
                    <option value="S3">Shift 3 - 9AM-9PM</option>
                    <option value="S4">Shift 4 - 10AM-10PM</option>
                    <option value="S5">Shift 5 - 11AM-11PM</option>
                    <option value="S6">Shift 6 - 12PM-11PM</option>
                    <option value="S7">Shift 7 - 2PM-11PM</option>
                  </select>
                </div>
              </div>

              {HereMerchant.length !== 0 && (
                <div className="sm:col-span-3 mt-4">
                  <label
                    htmlFor="reporting"
                    className="block text-sm font-medium leading-6 text-gray-900"
                  >
                    Print Report
                  </label>
                  <div className="mt-2 flex justify-center space-x-2.5">
                    <input
                      id="reporting"
                      name="reporting"
                      type="date"
                      className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                      value={startDate}
                      onChange={handleStartDateChange}
                    />
                    <input
                      id="reporting"
                      name="reporting"
                      type="date"
                      value={endDate}
                      onChange={handleEndDateChange}
                      min={startDate} // Ensure end date is no
                      className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                    />
                    {gene ? (
                      <div className="bg-slate-100 px-2 py-1.5 rounded-lg">
                        <div className="w-8 h-8 rounded-full border-4 border-red-500 border-t-transparent animate-spin"></div>
                      </div>
                    ) : reportlink ? (
                      <div className="flex justify-start items-center space-x-2.5">
                        <button
                          onClick={generateReport}
                          type="button"
                          className={` ${
                            startDate && endDate ? "bg-red-500" : "bg-red-100"
                          } hover:bg-red-500 text-white p-2 rounded-lg`}
                        >
                          Generate
                        </button>
                        <button
                          onClick={downloadFile}
                          type="button"
                          className="bg-red-500 hover:bg-red-500 text-white p-2 rounded-lg"
                        >
                          Download
                        </button>
                      </div>
                    ) : (
                      <button
                        onClick={generateReport}
                        type="button"
                        className={` ${
                          startDate && endDate ? "bg-red-500" : "bg-red-100"
                        } hover:bg-red-500 text-white p-2 rounded-lg`}
                      >
                        Generate
                      </button>
                    )}
                  </div>
                </div>
              )}
            </div>

            <div className="sm:col-span-3">
              <label
                htmlFor="telegram"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                TGID (Telegram ID) {formData.telegram ? 'Locked!' : 'Need to double check!'}
              </label>
              <div className="mt-2">
                <input
                  id="telegram"
                  name="telegram"
                  type="number"
                  placeholder="e.g 4871566"
                  maxLength={100}
                  className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                  value={formData.telegram}
                  readOnly={formData.telegram ? true : false}
                  onChange={handleChange}
                />
              </div>
              {errors.telegram && (
                <p className="text-red-500 text-sm">{errors.telegram}</p>
              )}
            </div>

            <div className="sm:col-span-3">
              <label
                htmlFor="phone"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Contact Number
              </label>
              <div className="mt-2">
                <input
                  id="phone"
                  name="phone"
                  type="text"
                  maxLength={11}
                  className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2 outline-none sm:text-sm sm:leading-6"
                  value={formData.phone}
                  onChange={handleChange}
                />
              </div>
              {errors.phone && (
                <p className="text-red-500 text-sm">{errors.phone}</p>
              )}
            </div>

            <div className="sm:col-span-3">
              <label
                htmlFor="ratings"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Ratings
              </label>
              <div className="mt-2">
                <input
                  id="ratings"
                  name="ratings"
                  type="number"
                  className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                  value={formData.ratings}
                  onChange={handleChange}
                  readOnly={HereMerchant === null ? true : false}
                />
              </div>
              {errors.ratings && (
                <p className="text-red-500 text-sm">{errors.ratings}</p>
              )}
            </div>

            <div className="sm:col-span-3">
              <label
                htmlFor="status"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Status
              </label>
              <div className="mt-2">
                <select
                  id="status"
                  name="status"
                  className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                  value={formData.status}
                  onChange={handleChange}
                >
                  <option value="Inactive">Inactive</option>
                  <option value="Active">Active</option>
                </select>
              </div>
            </div>

            <div className="sm:col-span-3">
              <label
                htmlFor="load"
                className="block text-xl font-bold leading-6 text-gray-900"
              >
                Wallet Account
              </label>
              <div className="mt-2 flex justify-start space-x-2">
                <div
                  onClick={() => checkBalance(formData.wallet)}
                  aria-readonly={encheck ? true : false}
                  className="flex space-x-2 hover:bg-red-500 hover:text-white w-48 rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2 outline-none sm:text-sm sm:leading-6"
                >
                  <p className="font-medium">Balance:</p>
                  <p className="font-medium font-mono">{formData.wallet}</p>
                </div>
                <input
                  id="load"
                  name="load"
                  type="text"
                  placeholder="Enter top-up amount"
                  maxLength={4}
                  onChange={(e) => setTopUpAmount(e.target.value)}
                  className="block w-48 rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:font-medium placeholder:text-gray-400 px-2 outline-none sm:text-sm sm:leading-6"
                  value={topupamount}
                />

                {toloading ? (
                  <div className="flex justify-center items-center">
                    <div className="h-8 w-8 rounded-full border-4 border-red-500 border-t-transparent animate-spin"></div>
                  </div>
                ) : (
                  <div className="flex justify-start items-center space-x-2.5">
                    <button
                      onClick={() => loadMeRider()}
                      type="button"
                      className={` ${
                        topupamount ? "bg-red-500" : "bg-red-100"
                      } hover:bg-red-500 text-white p-2 rounded-lg whitespace-nowrap`}
                    >
                      Top-up Account
                    </button>
                    <button
                      type="button"
                      className={` ${
                        topupamount ? "bg-red-500" : "bg-red-100"
                      } hover:bg-red-500 text-white p-2 rounded-lg`}
                    >
                      Deduct
                    </button>
                  </div>
                )}
              </div>
            </div>

            {/* shift schedule */}
            {/* <div className="col-span-full overflow-x-auto">
              <label
                htmlFor="address"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Shift Schedule
              </label>
              <div className="flex justify-between w-96">
                <label className="block text-sm font-medium leading-6 text-gray-400">
                  Day
                </label>
                <label className="mr-2 block text-sm font-medium leading-6 text-gray-400">
                  Open
                </label>
                <label className="mr-2 block text-sm font-medium leading-6 text-gray-400">
                  Close
                </label>
              </div>
              <div className="w-full gap-4 flex">
                <div className="w-16 my-1.5 block text-sm font-medium leading-6 text-gray-900">
                  <p className="text-center block w-16 font-medium rounded-md bg-white border border-gray-300 py-1.5 text-gray-600 shadow-sm  placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6">
                    Daily
                  </p>
                </div>
                <div className="w-56">
                  <div className="mt-2 flex">
                    <input
                      type="time"
                      className="block w-full font-medium rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                      value={startingOpen}
                      onChange={applyStarting}
                      placeholder="hh:mm"
                    />
                    <select
                      value=""
                      disabled
                      className="ml-2 block rounded-md px-2.5 border-0 py-1.5 text-gray-300 shadow-sm ring-1 font-medium ring-inset ring-gray-300 outline-none sm:text-sm sm:leading-6"
                    >
                      <option value="AM">AM</option>
                    </select>
                  </div>
                </div>
                <div className="w-56">
                  <div className="mt-2 flex">
                    <input
                      type="time"
                      className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 font-medium ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                      value={startingClose}
                      onChange={applyClosing}
                      placeholder="hh:mm"
                    />
                    <select
                      value=""
                      disabled
                      className="ml-2 block rounded-md px-2.5 border-0 py-1.5 text-gray-300 shadow-sm ring-1 font-medium ring-inset ring-gray-300 outline-none sm:text-sm sm:leading-6"
                    >
                      <option value="PM">PM</option>
                    </select>
                  </div>
                </div>
              </div>
              {days.map((day, index) => (
                <div key={day} className="w-full gap-4 flex">
                  <div className="w-16 my-1.5 block text-sm font-medium leading-6 text-gray-900">
                    <p className="text-center block w-16 sm:w-auto font-medium rounded-md bg-red-100 py-1.5 text-red-600 shadow-sm  placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6">
                      {day}
                    </p>
                  </div>
                  <div className="w-56">
                    <div className="mt-2 flex">
                      <input
                        type="time"
                        className="block w-full font-medium rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                        value={timeSchedule[index].openTime}
                        onChange={(e) =>
                          handleSchedTimeChange(
                            index,
                            "openTime",
                            e.target.value
                          )
                        }
                        placeholder="hh:mm"
                      />
                      <select
                        disabled
                        value={timeSchedule[index].openPeriod}
                        onChange={(e) =>
                          handleSchedTimeChange(
                            index,
                            "openPeriod",
                            e.target.value
                          )
                        }
                        className="ml-2 block rounded-md px-2.5 border-0 py-1.5 text-gray-400 shadow-sm ring-1 font-medium ring-inset ring-gray-300 outline-none sm:text-sm sm:leading-6"
                      >
                        <option value="AM">AM</option>
                        <option value="PM">PM</option>
                      </select>
                    </div>
                  </div>
                  <div className="w-56">
                    <div className="mt-2 flex">
                      <input
                        type="time"
                        className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 font-medium ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                        value={timeSchedule[index].closeTime}
                        onChange={(e) =>
                          handleSchedTimeChange(
                            index,
                            "closeTime",
                            e.target.value
                          )
                        }
                        placeholder="hh:mm"
                      />
                      <select
                        disabled
                        value={timeSchedule[index].closePeriod}
                        onChange={(e) =>
                          handleSchedTimeChange(
                            index,
                            "closePeriod",
                            e.target.value
                          )
                        }
                        className="ml-2 block rounded-md px-2.5 border-0 py-1.5 text-gray-400 shadow-sm ring-1 font-medium ring-inset ring-gray-300 outline-none sm:text-sm sm:leading-6"
                      >
                        <option value="AM">AM</option>
                        <option value="PM">PM</option>
                      </select>
                    </div>
                  </div>
                </div>
              ))}
            </div> */}
          </div>
        </div>
      </div>

      <div className="mt-6 flex items-center justify-end gap-x-6">
        {loading ? (
          <LoadingButton />
        ) : (
          uploadProgress === 0 && (
            <button
              type="submit"
              className="w-56 rounded-md bg-red-600 px-3 py-2.5 text-lg text-white shadow-sm hover:bg-[#ff1616] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-600"
            >
              {HereMerchant.length !== 0
                ? "Update Rider"
                : "Create Rider Account"}
            </button>
          )
        )}
      </div>
      <Toast2 visible={errorShow} message={errormsg} />
    </form>
  );
};

function RiderPage({ private_Date, setSideMenuOpen, activeSideMenu }) {
  const [activeScreen, setAScreen] = useState("TABLE"); // Default screen

  const changeView = (screen) => {
    setAScreen(screen);
  };

  const back2Merchant = () => {
    setAScreen("TABLE");
    setManage(null);
  };

  const [HereMerchant, setManage] = useState(null);
  const ManageStore = (it) => {
    setAScreen("CREATE");
    setManage(it);
  };

  const [openData, setOpenData] = useState([]);
  const openStore = (store) => {
    setAScreen("LOAD");
    setOpenData(store);
  };

  const [StoreProduct, SetStoreProduct] = useState([]);
  const [editProduct, setEditProduct] = useState([]);

  const AddProduct = () => {
    setEditProduct([]);
    setAScreen("ADD");
  };

  const EditNga = () => {
    setAScreen("ADD");
  };

  const renderScreen = () => {
    switch (activeScreen) {
      case "CREATE":
        return (
          <CreateMerchant
            private_Date={private_Date}
            HereMerchant={HereMerchant}
          />
        );
      default:
        return <LoadPartners openStore={openStore} ManageStore={ManageStore} />;
    }
  };

  return (
    <div className="bg-white">
      <nav className="block  lg:hidden bg-red-500 top-2 h-14 shadow-xl w-full">
        <button
          onClick={() => setSideMenuOpen(!activeSideMenu)}
          className="block lg:hidden absolute top-2.5 left-2 bg-white p-2 rounded-lg shadow-xl"
        >
          <BurgerIcon c="#dc2626" w={20} h={20} />
        </button>
      </nav>
      <div className="p-4">
        <div className="flex justify-between items-center">
          <div className="flex justify-start space-x-2.5 items-center">
            {activeScreen === "LOAD" && (
              <div onClick={back2Merchant} className="cursor-pointer">
                <ArrowLeftBig c="#404040" h="20" w="20" />
              </div>
            )}
            <BigGreetingsTitle
              text={
                activeScreen === "LOAD"
                  ? openData.StoreName
                  : activeScreen === "ADD"
                  ? "Add Product"
                  : "Riders"
              }
            />
            <div className="cursor-pointer bg-gray-300 w-px h-8"></div>
          </div>
          <div className="flex justify-start items-center space-x-2">
            {activeScreen === "CREATE" ? (
              <Button1 click={back2Merchant} text="Back to Riders" />
            ) : (
              <>
                {activeScreen === "LOAD" ? (
                  <ButtonAdd text="Add Product" click={AddProduct} />
                ) : activeScreen === "ADD" ? (
                  <Button1 click={() => openStore(openData)} text="Close" />
                ) : (
                  <ButtonAdd
                    click={() => changeView("CREATE")}
                    text="Create Rider"
                  />
                )}
              </>
            )}
          </div>
        </div>

        {renderScreen()}
      </div>
    </div>
  );
}

export default RiderPage;
