import { StarIcon } from "../components/icons";

const FeedbackPage = () => {
  const [allreviewX, saveReviews] = useState([]);
  const [overallStar, setOverall] = useState(2);

  const renderStars = (rating) => {
    const totalStars = 5;
    const stars = [];

    for (let i = 1; i <= totalStars; i++) {
      stars.push(
        <StarIcon
          key={i}
          c={i <= rating ? "#eab308" : "#d1d5db"}
          w="20"
          h="20"
        />
      );
    }

    return (
      <div className="flex justify-start items-center space-x-1">{stars}</div>
    );
  };

  const calculateAverageRating = (data) => {
    if (data.length === 0) return 0;

    const totalRatings = data.reduce(
      (sum, item) => sum + parseFloat(item.Ratings),
      0
    );
    return totalRatings / data.length;
  };

  return (
    <div>
      {allreviewX.length !== 0 && (
        <div className="p-4">
          <p className="text-2xl font-medium text-gray-600">Overall Ratings</p>
          <div className="flex justify-center items-center space-x-2 border border-gray-300 shadow-md px-2.5 py-1.5 w-36 my-2 text-center bg-white rounded-lg">
            <div>
              <StarIcon c="#eab308" w="18" h="18" />
            </div>
            <p className="text-md font-medium">{overallStar}</p>
          </div>
        </div>
      )}
      <div>
        {allreviewX.length === 0 && (
          <div className="border-t border-gray-300 flex justify-center items-center p-8">
            <p className="text-2xl font-medium text-gray-300">No reviews yet</p>
          </div>
        )}

        {allreviewX.map((rev) => (
          <div className="flex justify-start items-center space-x-2.5 p-4 border border-gray-300 my-2.5 rounded-lg">
            <div className="bg-slate-200 px-4 py-2.5 rounded-lg">
              <p>{rev.Ratings}</p>
            </div>
            <div className="pl-4 w-full">
              <div className="md:flex lg:flex justify-between items-center">
                <div>{renderStars(rev.Ratings)}</div>
                <p className="text-gray-500 px-2 py-1.5 rounded-lg">
                  {rev.Date}
                </p>
              </div>
              <p className="text-gray-600">"{rev.Comments}"</p>
              <div>
                <p className="pl-4 text-gray-500 my-2 text-sm">
                  - Review by{" "}
                  <span className="font-medium text-gray-800">
                    {rev.Reviewer}
                  </span>
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default FeedbackPage;
