import {
  collection,
  doc,
  getFirestore,
  onSnapshot,
  query,
  serverTimestamp,
  setDoc,
} from "firebase/firestore";
import { getMessaging } from "firebase/messaging";
import "./App.css";
import SetMapPage from "./screens/app-map";
import HomePage from "./screens/home";
import LoginPage from "./screens/login";
import LiveMapPage from "./screens/tracker";
import VerifyPage from "./screens/verify";

import { initializeApp } from "firebase/app";

const firebaseConfig = {
  apiKey: "AIzaSyDJUIhJ0OIK0-KHNBFsTGFlth-mvIKviHQ",
  authDomain: "keepadmin.firebaseapp.com",
  projectId: "keepadmin",
  storageBucket: "keepadmin.appspot.com",
  messagingSenderId: "1046515623488",
  appId: "1:1046515623488:web:1ba2f626145405fcc621a5",
  measurementId: "G-79Z663VBGG",
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const messaging = getMessaging(app);

function App() {
  const [user, setUser] = useState(null);
  const [goOnline, setStatus] = useState(false);
  const [private_Date, setPrivData] = useState([]);
  const [chatOpen, chatPop] = useState(false);
  const [whoChat, setwhoChat] = useState(null);

  const db = getFirestore();

  // useEffect(() => {
  //   // Initialize OneSignal and prompt the user for notification permissions
  //   window.OneSignal = window.OneSignal || [];
  //   window.OneSignal.push(() => {
  //     window.OneSignal.init({
  //       appId: "45695007-3e27-43e5-8489-ec11f20e5244",
  //     });

  //     // Prompt user to subscribe to notifications
  //     window.OneSignal.push(() => {
  //       window.OneSignal.isPushNotificationsEnabled((isEnabled) => {
  //         if (!isEnabled) {
  //           window.OneSignal.showSlidedownPrompt();
  //         }
  //       });
  //     });

  //     // Handle background/foreground messages
  //     window.OneSignal.on('notificationDisplay', (event) => {
  //       console.log('OneSignal notification displayed:', event);
  //     });
  //   });

  // }, []);

  const [isActive, setIsActive] = useState(true);

  useEffect(() => {
    const handleUserActivity = () => {
      setIsActive(true);
    };

    window.addEventListener("click", handleUserActivity);
    window.addEventListener("keypress", handleUserActivity);

    return () => {
      window.removeEventListener("click", handleUserActivity);
      window.removeEventListener("keypress", handleUserActivity);
    };
  }, []);

  let audio; // Declare audio variable outside
  let isPlaying = false;
  const playSound = () => {
    if (!audio) {
      // Initialize audio only if it hasn't been initialized
      audio = new Audio("https://kiefers-app.com/assets/sounds/htc_alarm.mp3");
      audio.loop = false; // Set looping
    }

    // Play sound only if it's not already playing
    if (!isPlaying) {
      audio
        .play()
        .catch((error) => console.error("Error playing sound:", error));
      isPlaying = true; // Set flag to true
    }
  };

  const stopSound = () => {
    if (audio) {
      audio.pause(); // Pause the audio
      audio.currentTime = 0; // Reset the audio to the beginning
      isPlaying = false;
    }
  };

  useEffect(() => {
    // Check if user data is in local storage
    const storedUser = localStorage.getItem("user");
    if (storedUser) {
      setUser(JSON.parse(storedUser));
      setStatus(true);
    }

    if (!private_Date) {
    }

    async function handleOnline(userEmail) {
      try {
        await setDoc(doc(db, "onlineUsers", userEmail), {
          loginTime: serverTimestamp(),
          image: private_Date.Profile,
        });
      } catch (error) {
        console.error("Error adding document: ", error);
      }
    }

    //record active
    if (isActive) {
      const userKID = JSON.parse(storedUser);
      // Reset the active state after a certain time period

      if (userKID) {
        //console.log(userKID);
        const MeFIB = userKID.account || null;
        const onli = handleOnline(MeFIB);
      }

      const timeout = setTimeout(() => setIsActive(false), 3000); // 3 seconds for example
      return () => clearTimeout(timeout);
    }

    const chatRoomsCollection = collection(db, "ChatRooms");

    const listenToWaiveChanges = () => {
      const unsubscribeFunctions = [];

      onSnapshot(chatRoomsCollection, (snapshot) => {
        snapshot.forEach((doc) => {
          const roomId = doc.id;
          const aliveCollection = collection(db, "ChatRooms", roomId, "alive");

          const aliveQuery = query(aliveCollection);

          const unsubscribe = onSnapshot(aliveQuery, (aliveSnapshot) => {
            aliveSnapshot.forEach((aliveDoc) => {
              const waiveData = aliveDoc.data();
              chatPop(waiveData.waive);
              if (waiveData.waive === true) {
                setwhoChat(roomId);
                if (!isPlaying) {
                  playSound(); // Play sound if waive is true
                }
              } else {
                setwhoChat(null);
                stopSound(); // Stop sound if waive is false
              }
            });
          });

          unsubscribeFunctions.push(unsubscribe);
        });
      });

      // Return a function to unsubscribe all listeners when no longer needed
      return () => unsubscribeFunctions.forEach((unsubscribe) => unsubscribe());
    };

    listenToWaiveChanges();
  }, [setUser, isActive, setwhoChat]);

  const handleLogin = (userData) => {
    setStatus(true);
    setUser(userData);
    localStorage.setItem("user", JSON.stringify(userData));
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");

    setUser(null);
  };

  {
    /* <Router>
  <Routes>
    <Route path="/login" element={<LoginPage setPrivData={setPrivData} onLogin={handleLogin} />} />
    <Route path="/verify" element={<VerifyPage />} />
    <Route path="/home/*" element={goOnline ? <HomePage whoChat={whoChat} chatOpen={chatOpen} private_Date={private_Date} onLogout={handleLogout} /> : <Navigate to="/login" />} />
    <Route path="/" element={<Navigate to="/login" />} />
  </Routes>
</Router> */
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/setlocation" element={<SetMapPage />} />
        <Route path="/tracker" element={<LiveMapPage />} />
        <Route
          path="/login"
          element={
            <LoginPage setPrivData={setPrivData} onLogin={handleLogin} />
          }
        />
        <Route path="/verify" element={<VerifyPage />} />
        <Route
          path="/home/*"
          element={
            goOnline ? (
              <HomePage
                whoChat={whoChat}
                chatOpen={chatOpen}
                private_Date={private_Date}
                onLogout={handleLogout}
              />
            ) : (
              <Navigate to="/login" />
            )
          }
        />
        <Route path="/" element={<Navigate to="/login" />} />
      </Routes>
    </HashRouter>
  );
}

export default App;
