import React from "react";

export const StaticMap = ({ data }) => {
  // Split the data and remove whitespace using trim()
  const [latitude, longitude] = data.split(",").map((coord) => coord.trim());

  const accessToken =
    "pk.eyJ1IjoibWFyaWExMDIwMjQiLCJhIjoiY20yd29uN3gxMDljNTJqcHdreHBuaXJrbyJ9.t2UfftJcFzJNjyhBZL3bnw";

  // Construct the map URL with the cleaned latitude and longitude
  const mapUrl = `https://api.mapbox.com/styles/v1/mapbox/streets-v12/static/pin-s+ff0000(${longitude},${latitude})/${longitude},${latitude},15.03,0/200x200?logo=false&access_token=${accessToken}`;

  return (
    <div>
      <img
        src={mapUrl}
        alt={data}
        className="object-center border border-gray-200 rounded-lg w-14 h-14"
      />
    </div>
  );
};

