import axios from "axios";
import React, { useEffect, useState } from "react";
import {
  Button1,
  ButtonAdd,
  ButtonWithIcon,
  LoadingButton,
} from "../components/button";
import {
  AddIcon,
  ArrowLeftBig,
  BurgerIcon,
  CloseIcon,
  SettingsIcon,
  TicketIcon,
} from "../components/icons";
import { Loader } from "../components/loader";
import { BigGreetingsTitle } from "../components/title";
import { Toast2 } from "../components/toast";

const LoadPartners = ({ ManageStore, openStore }) => {
  // const allpartners = NearbyStore();
  const [allpartners, setPartners] = useState([]);
  useEffect(() => {
    const fetchPartners = async () => {
      try {
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/coupon/pullcoupon/",
          {
            access: null,
          }
        );

        const alldata = response.data;

        if (alldata.status) {
          setPartners(alldata.vouchers);
        }
      } catch (e) {
        console.log(e);
      }
    };

    fetchPartners();
  }, [setPartners]);

  return (
    <section className="rounded-t-xl max-h-[85vh] bg-white overflow-x-auto w-full">
      <table className="rounded-t-xl table-auto border-collapse whitespace-nowrap w-full">
        <thead className="sticky top-0 bg-[#ff1616] p-4 rounded-t-xl border dark:border-gray-700 relative w-full">
          <tr className="leading-none  z-50 snap-center p-4">
            <th className="text-white text-center relative p-2.5 font-normal">
              Coupon Code
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Value
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Expiration
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Status
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Created
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Owner
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Limit
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Times Used
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Manage
            </th>
          </tr>
        </thead>
        <tbody className="bg-white">
          {allpartners.map((store) => (
            <tr
              onClick={() => ManageStore(store)}
              className="hover:bg-red-50 border border-gray-300 "
              key={store.VoucherID}
            >
              <td className="text-center">
                <div className="flex justify-start items-center space-x-2.5 px-2.5">
                  <div className="flex justify-start space-x-2 items-center w-auto bg-white border border-gray-300 shadow-md text-gray-600 px-2 py-0.5 rounded-lg ">
                    <TicketIcon c="#fecaca" w="20" h="20" />
                    <p>{store.Code}</p>
                  </div>
                </div>
              </td>

              <td className="text-center ">
                <p className="font-mono">
                  {store.Type === "Amount"
                    ? "₱" + store.Amount + " w/ min. of ₱" + store.Minimum
                    : store.Amount + "%"}
                </p>
              </td>

              <td className="text-left">
                <div className="text-center px-2.5">{store.Expiration}</div>
              </td>

              <td className="text-center">
                <div
                  className={`${
                    store.Status === "Active"
                      ? "bg-green-500 text-white"
                      : "bg-slate-200 text-gray-600"
                  } px-2 py-0.5 mx-2.5 rounded-lg`}
                >
                  {store.Status}
                </div>
              </td>

              <td className="text-center font-mono">{store.Created}</td>

              <td className="w-48 truncate text-center ">
                <p>{store.StoreName}</p>
              </td>

              <td className="truncate text-center ">
                <p>{store.Quota}</p>
              </td>

              <td className="truncate text-center ">
                <p>{store.Used}</p>
              </td>

              <td className="text-center">
                <div className="p-2.5">
                  <ButtonWithIcon
                    press={() => ManageStore(store)}
                    children={<SettingsIcon c="#dc2626" w="18" h="18" />}
                    title="Manage"
                  />
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {allpartners.length === 0 && (
        <div className="h-96 flex justify-center items-center p-8">
          <Loader />
        </div>
      )}
    </section>
  );
};

const CreateMerchant = ({ HereMerchant, openData }) => {
  console.log(HereMerchant);
  if (HereMerchant === null) {
    var HereMerchant = [];
  }

  const [allproducts, setProducts] = useState([]);
  const [selectedProducts2, setPro2] = useState([]);

  const [selectedFoods, setSelectedFoods] = useState([]);
  const [newFood, setNewFood] = useState("");

  useEffect(() => {
    const LoadALL = async () => {
      try {
        const response = await axios.get(
          `https://kiapifers-dlver.cloud/merchant/getmerchantproduct/?Email=${HereMerchant.MerchantEmail}&StoreName=${HereMerchant.StoreName}`
        );
        var tempra = response.data.products;
        setProducts(response.data.products);
        var selected2 = (HereMerchant.Products || "")
          .split(",")
          .map((id) => id.trim())
          .map((id) => tempra.find((food) => food.ProductID === id))
          .filter(Boolean);
        setSelectedFoods(selected2);
      } catch (e) {
        console.log(e);
      }
    };

    LoadALL();
  }, [setProducts]);

  // const selectedProducts2 = (HereMerchant.Products || "" )
  //   .split(',')
  //   .map(id => id.trim())
  //   .map(id => allproducts.find(food => food.ProductID === id))
  //   .filter(Boolean);

  // useEffect(() => {
  //   if (selectedFoods.length === 0) {
  //     setSelectedFoods(selectedProducts2 || []);
  //   }
  // }, [selectedProducts2]);

  const handleSelectFood = () => {
    const selectedProduct = newFood;
    const selectedFood = allproducts.find(
      (food) => food.Product === selectedProduct
    );

    if (selectedFood) {
      const isAlreadySelected = selectedFoods.some(
        (food) => food.Product === selectedProduct
      );

      if (!isAlreadySelected) {
        setSelectedFoods([...selectedFoods, selectedFood]);
      }
    }

    setNewFood("");
  };

  const handleInputChange = (e) => {
    setNewFood(e.target.value);
  };

  const handleRemoveFood = (index) => {
    setSelectedFoods(selectedFoods.filter((_, i) => i !== index));
  };

  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setTimeout(() => {
      setShow("hidden");
    }, 5000);
  };

  const [formData, setFormData] = useState({
    code: HereMerchant.Code || "KIEFERSAPP",
    value: HereMerchant.Amount || 30,
    limit: HereMerchant.Quota || 0,
    status: HereMerchant.Status || "Inactive",
    mode: HereMerchant.Type || "Percentage",
    expire: HereMerchant.Expiration || "1D",
    minimum: HereMerchant.Minimum || 90,
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData({
      ...formData,
      [name]: type === "checkbox" ? checked : value,
    });
    console.log(e.target.value);
  };

  const ResetNga = () => {
    setFormData({
      code: HereMerchant.Code || "KIEFERSAPP",
      value: HereMerchant.Amount || 30,
      limit: HereMerchant.Quota || 0,
      status: HereMerchant.Status || "Inactive",
      mode: HereMerchant.Type || "Percentage",
      expire: HereMerchant.Expiration || "1D",
      minimum: HereMerchant.Minimum || 90,
    });

    setUploadProgress(0);
  };

  const [uploadProgress, setUploadProgress] = useState(0);

  const validate = () => {
    const newErrors = {};

    if (!formData.code) newErrors.about = "Coupon name is required";
    if (!formData.value) newErrors.expire = "Value is required";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const [loading, setLoading] = useState(false);
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    const data = new FormData();
    for (const key in formData) {
      data.append(key, formData[key]);
    }

    try {
      setLoading(true);

      const productIDs = selectedFoods.map((food) => food.ProductID);

      var boday = {
        Email: "app@kiefers.com",
        StoreName: "Kiefers Bot",
        Amount: formData.value,
        Expiration: formData.expire,
        Code: formData.code,
        Type: formData.mode,
        Minimum: formData.minimum,
        Quota: formData.limit,
        Status: formData.status,
        VoucherID: HereMerchant.VoucherID,
        Products: productIDs.join(", "),
      };
      var api = "https://kiapifers-dlver.cloud/coupon/updatecoupon/";
      if (HereMerchant === null || HereMerchant.length === 0) {
        api = "https://kiapifers-dlver.cloud/coupon/createcoupon/";
        boday = {
          Email: "app@kiefers.com",
          StoreName: "Kiefers Bot",
          Amount: formData.value,
          Expiration: formData.expire,
          Code: formData.code,
          Type: formData.mode,
          Minimum: formData.minimum,
          Quota: formData.limit,
          Status: formData.status,
          Products: productIDs.join(", "),
        };
      }

      const response = await axios.post(api, boday, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      console.log(response.data);
      setLoading(false);
      showAlert(
        HereMerchant === null || HereMerchant.length === 0
          ? "Successfully Added!"
          : "Updated!"
      );
      ResetNga();
    } catch (error) {
      console.error(error);
      showAlert("Please try again. Error!");
      setLoading(false);
    }
  };

  const today = new Date().toISOString().split("T")[0];

  return (
    <form className="px-2.5" onSubmit={handleSubmit}>
      <div className="space-y-12">
        <div className="border-b border-gray-900/10 pb-12">
          <h2 className="text-base font-semibold leading-7 text-gray-900">
            Coupon Information
          </h2>
          <p className="mt-1 text-sm leading-6 text-gray-600">
            This information will be displayed publicly so be careful what you
            inputs,{" "}
            <span className="text-red-500 font-medium">ask for a review</span>.
          </p>

          <div className="mt-10 flex gap-x-6">
            <div className="w-[600px] flex justify-start">
              <div className="w-full">
                <div className="bg-red-50 rounded-lg py-2.5 flex justify-center w-full">
                  {formData.mode === "Percentage" ? (
                    <div className="relative">
                      <div className="w-72 h-28 bg-yellow-400 rounded-xl flex justify-start items-center">
                        <div className="px-6">
                          <h1 className="font-bold text-red-600 text-4xl">
                            {formData.value}%
                          </h1>
                          <p className="font-bold text-red-600 text-xl text-right">
                            off!
                          </p>
                        </div>

                        <div className="py-4 px-2 border-l-2 border-dashed border-white h-28">
                          <p className="text-white text-lg text-center">
                            Let's Coupon
                          </p>
                          <p className="shadow-md my-2.5 bg-[#ff1616] rounded-xl px-2.5 py-1.5 text-white text-center text-lg font-medium">
                            {formData.code}
                          </p>
                        </div>
                      </div>

                      <div className="absolute mx-auto inset-0 h-28 flex justify-between items-center w-72">
                        <div className="-left-8 absolute top-8 w-12 h-12 bg-red-50 rounded-full "></div>
                        <div className="-right-8 absolute top-8 w-12 h-12 bg-red-50 rounded-full "></div>
                      </div>
                    </div>
                  ) : formData.mode === "Amount" ? (
                    <div className="relative">
                      <div className="w-72 h-28 bg-[#ff1616] rounded-xl flex justify-start items-center">
                        <div className="pl-6 pr-4">
                          <div className="rotate-45">
                            <TicketIcon c="#fff" w="30" h="30" />
                          </div>
                        </div>

                        <div className="py-4 px-2 border-l-2 border-dashed border-white h-28">
                          <p className="text-white font-medium text-lg">
                            &#8369;{formData.value} off{" "}
                            <span className="text-yellow-200 font-bold">
                              {formData.code}
                            </span>
                          </p>
                          <p className="text-sm mt-1.5 text-red-100">
                            Min order of &#8369;{formData.minimum} valid for all
                            items. Enjoy!
                          </p>
                        </div>
                      </div>

                      <div className="absolute mx-auto inset-0 h-28 flex justify-between items-center w-72">
                        <div className="-left-8 absolute top-8 w-12 h-12 bg-red-50 rounded-full "></div>
                        <div className="-right-8 absolute top-8 w-12 h-12 bg-red-50 rounded-full "></div>
                      </div>
                    </div>
                  ) : (
                    <div className="relative">
                      <div className="w-72 h-28 bg-[#ff1616] rounded-xl flex justify-start items-center">
                        <div className="pl-6 pr-4">
                          <div className="rotate-45">
                            <TicketIcon c="#fff" w="30" h="30" />
                          </div>
                        </div>

                        <div className="py-4 px-2 border-l-2 border-dashed border-white h-28">
                          <p className="text-white font-medium text-lg">
                            {formData.value}% off{" "}
                            <span className="text-yellow-200 font-bold">
                              {formData.code}
                            </span>
                          </p>
                          <p className="text-sm mt-1.5 text-red-100">
                            Min. distance of {formData.minimum}km. Enjoy!
                          </p>
                        </div>
                      </div>

                      <div className="absolute mx-auto inset-0 h-28 flex justify-between items-center w-72">
                        <div className="-left-8 absolute top-8 w-12 h-12 bg-red-50 rounded-full "></div>
                        <div className="-right-8 absolute top-8 w-12 h-12 bg-red-50 rounded-full "></div>
                      </div>
                    </div>
                  )}
                </div>

                <div className="p-2 rounded-lg border my-2 border-gray-300 w-auto">
                  {allproducts.length === 0 ? (
                    <div className="p-8">
                      <h1 className="text-lg text-center text-gray-300 font-medium">
                        No products found
                      </h1>
                    </div>
                  ) : (
                    <div>
                      <div className="flex justify-between items-center">
                        <p className="font-medium text-lg">
                          Valid Items for this coupon.
                        </p>
                        <div className="flex justify-end space-x-2.5">
                          <input
                            list="required-foods"
                            id="required-food-input"
                            value={newFood}
                            onChange={handleInputChange}
                            placeholder="Choose or type food"
                            className="outline-none border border-gray-300 px-2.5 py-1.5 rounded-xl"
                          />
                          <datalist id="required-foods">
                            {allproducts.map((food, index) => (
                              <option key={index} value={food.Product} />
                            ))}
                          </datalist>
                          <div
                            onClick={handleSelectFood}
                            className="cursor-pointer px-2.5 py-1.5 flex justify-center items-center space-x-2 bg-[#ff1616] rounded-lg shadow mx-2 text-white"
                          >
                            <AddIcon c="#fff" w="15" h="15" />
                            <span>Add</span>
                          </div>
                        </div>
                      </div>

                      <ul className="h-auto max-h-48 overflow-y-auto flex flex-wrap p-2.5 mt-4 gap-2 rounded-lg border border-gray-300">
                        {selectedFoods.map((food, index) => (
                          <li
                            key={index}
                            className="group p-2 border border-gray-300 rounded-lg flex justify-between items-center space-x-2.5 w-68"
                          >
                            <img
                              src={food.Image}
                              alt={food.Product}
                              className="object-cover w-16 h-16 rounded-lg"
                            />
                            <div className="w-40 truncate">
                              <p>{food.Product}</p>
                              <p className="text-gray-500 text-xs truncate w-28">
                                {food.Description}
                              </p>
                              <div className="flex justify-between items-center">
                                {food.Discounted == "" ||
                                food.Discounted == "0" ? (
                                  <p className="text-red-500 text-xs">
                                    &#8369;{Math.round(parseInt(food.Price))}
                                  </p>
                                ) : (
                                  <div className="flex justify-start items-center space-x-2.5">
                                    <p className="text-gray-300 text-xs">
                                      &#8369;{Math.round(parseInt(food.Price))}
                                    </p>
                                    <p className="text-red-500 text-xs">
                                      &#8369;
                                      {Math.round(parseInt(food.Discounted))}
                                    </p>
                                  </div>
                                )}
                                <div className="space-x-1.5 flex justify-start items-center bg-yellow-500 px-2 py-0.5 rounded-lg">
                                  <div className="rotate-45">
                                    <TicketIcon c="#fff" w="12" h="12" />
                                  </div>
                                  <p className="text-xs font-medium text-white">
                                    {formData.code}
                                  </p>
                                </div>
                              </div>
                            </div>
                            <button
                              type="button"
                              onClick={() => handleRemoveFood(index)}
                              className="hidden group-hover:inline-flex cursor-pointer flex justify-center items-center bg-slate-200 h-6 w-6 rounded-full"
                            >
                              <CloseIcon c="#404040" w="16" h="16" />
                            </button>
                          </li>
                        ))}

                        {selectedFoods.length === 0 && (
                          <div>
                            <p className="text-gray-500 p-4">Add a product</p>
                          </div>
                        )}
                      </ul>
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="w-96">
              <label
                htmlFor="code"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Coupon Code
              </label>
              <div className="mt-2">
                <textarea
                  id="code"
                  name="code"
                  rows={1}
                  placeholder="e.g HAPPYMEAL"
                  maxLength={10}
                  className={`block w-full rounded-md border-0 py-1.5 px-2.5 ${
                    HereMerchant.length === 0
                      ? "text-gray-900"
                      : "cursor-not-allowed text-gray-300"
                  }  shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 outline-none sm:text-sm sm:leading-6`}
                  value={formData.code}
                  onChange={handleChange}
                  readOnly={HereMerchant.length === 0 ? false : true}
                />
              </div>
              {errors.code && (
                <p className="text-red-500 text-sm">{errors.code}</p>
              )}

              <div className="mt-4">
                <label
                  htmlFor="mode"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Value
                </label>
                <div className="flex justify-start items-center space-x-2.5">
                  <div>
                    <select
                      id="mode"
                      name="mode"
                      className={`block w-auto rounded-md border-0 py-1.5 ${
                        HereMerchant.length === 0
                          ? "text-gray-900"
                          : "cursor-not-allowed text-gray-300"
                      } shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6`}
                      value={formData.mode}
                      onChange={handleChange}
                      disabled={HereMerchant.length === 0 ? false : true}
                    >
                      <option value="Percentage">Percentage</option>
                      <option value="Amount">Amount</option>
                      <option value="Kilometer">Kilometer</option>
                    </select>
                  </div>

                  <div>
                    <input
                      id="value"
                      name="value"
                      type="number"
                      min={0}
                      placeholder="Enter value"
                      maxLength={3}
                      className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                      value={formData.value}
                      onChange={handleChange}
                    />
                  </div>
                  {errors.value && (
                    <p className="text-red-500 text-sm">{errors.value}</p>
                  )}

                  {formData.mode == "Amount" ||
                    (formData.mode == "Kilometer" && (
                      <div className="relative">
                        {formData.mode == "Amount" && (
                          <div className="left-2 top-1.5 absolute">&#8369;</div>
                        )}

                        <input
                          id="minimum"
                          name="minimum"
                          type="number"
                          min={0}
                          placeholder="Enter Minimun"
                          maxLength={3}
                          className="block w-full rounded-md border-0 py-1.5 pl-5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                          value={formData.minimum}
                          onChange={handleChange}
                        />

                        {formData.mode == "Kilometer" ? (
                          <p className="-bottom-4 absolute text-xs text-gray-500 mt-1.5">
                            Minimum kilometer
                          </p>
                        ) : (
                          <p className="-bottom-4 absolute text-xs text-gray-500 mt-1.5">
                            Minimum amount order
                          </p>
                        )}
                      </div>
                    ))}
                  {errors.minimum && (
                    <p className="text-red-500 text-sm">{errors.minimum}</p>
                  )}
                </div>
              </div>

              <div className="mt-4">
                <label
                  htmlFor="limit"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Allowed Uses
                </label>
                <input
                  id="limit"
                  name="limit"
                  type="number"
                  placeholder="1"
                  min={0}
                  maxLength={1000}
                  className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                  value={formData.limit}
                  onChange={handleChange}
                />
              </div>

              <div className="mt-4">
                <label
                  htmlFor="status"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Status
                </label>
                <div className="mt-2">
                  <select
                    id="status"
                    name="status"
                    className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                    value={formData.status}
                    onChange={handleChange}
                  >
                    <option value="Inactive">Inactive</option>
                    <option value="Active">Active</option>
                  </select>
                </div>
              </div>

              <div className="mt-4">
                <label
                  htmlFor="expire"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Expiration
                </label>
                <div className="mt-2">
                  <input
                    id="expire"
                    name="expire"
                    type="date"
                    min={today}
                    className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                    value={formData.expire}
                    onChange={handleChange}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-6 flex items-center justify-end gap-x-6">
        {loading ? (
          <LoadingButton />
        ) : (
          uploadProgress === 0 && (
            <button
              type="submit"
              className="w-56 rounded-md bg-red-600 px-3 py-2.5 text-lg text-white shadow-sm hover:bg-[#ff1616] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-600"
            >
              {HereMerchant.length !== 0 ? "Update" : "Create"}
            </button>
          )
        )}
      </div>
      <Toast2 visible={errorShow} message={errormsg} />
    </form>
  );
};

function CouponPage({ setSideMenuOpen, activeSideMenu }) {
  const [activeScreen, setAScreen] = useState("TABLE"); // Default screen

  const changeView = (screen) => {
    setAScreen(screen);
  };

  const back2Merchant = () => {
    setAScreen("TABLE");
    setManage(null);
  };

  const [HereMerchant, setManage] = useState(null);
  const ManageStore = (it) => {
    setAScreen("CREATE");
    setManage(it);
  };

  const [openData, setOpenData] = useState([]);
  const openStore = (store) => {
    setAScreen("LOAD");
    setOpenData(store);
  };

  const [StoreProduct, SetStoreProduct] = useState([]);
  const [editProduct, setEditProduct] = useState([]);

  const AddProduct = () => {
    setEditProduct([]);
    setAScreen("ADD");
  };

  const EditNga = () => {
    setAScreen("ADD");
  };

  const renderScreen = () => {
    switch (activeScreen) {
      case "CREATE":
        return <CreateMerchant HereMerchant={HereMerchant} />;
      default:
        return <LoadPartners openStore={openStore} ManageStore={ManageStore} />;
    }
  };

  return (
    <div className="bg-white">
      <nav className="block  lg:hidden bg-red-500 top-2 h-14 shadow-xl w-full">
        <button
          onClick={() => setSideMenuOpen(!activeSideMenu)}
          className="block lg:hidden absolute top-2.5 left-2 bg-white p-2 rounded-lg shadow-xl"
        >
          <BurgerIcon c="#dc2626" w={20} h={20} />
        </button>
      </nav>
      <div className="p-4">
        <div className="flex justify-between items-center">
          <div className="flex justify-start space-x-2.5 items-center">
            {activeScreen === "LOAD" && (
              <div onClick={back2Merchant} className="cursor-pointer">
                <ArrowLeftBig c="#404040" h="20" w="20" />
              </div>
            )}
            <BigGreetingsTitle
              text={
                activeScreen === "LOAD"
                  ? openData.StoreName
                  : activeScreen === "ADD"
                  ? "Add Product"
                  : "Coupons"
              }
            />
            <div className="cursor-pointer bg-gray-300 w-px h-8"></div>
          </div>
          <div className="flex justify-start items-center space-x-2">
            {activeScreen === "CREATE" ? (
              <Button1 click={back2Merchant} text="Back to Coupon" />
            ) : (
              <>
                {activeScreen === "LOAD" ? (
                  <ButtonAdd text="Add Product" click={AddProduct} />
                ) : activeScreen === "ADD" ? (
                  <Button1 click={() => openStore(openData)} text="Close" />
                ) : (
                  <ButtonAdd
                    click={() => changeView("CREATE")}
                    text="Create Coupon"
                  />
                )}
              </>
            )}
          </div>
        </div>

        {renderScreen()}
      </div>
    </div>
  );
}

export default CouponPage;
