import axios from "axios";
import { useState } from "react";
import { CloseIcon } from "./icons";

export function Modal1({
  show,
  showModaal,
  newEmail,
  setNewEmail,
  duplicateMerchant,
}) {
  return (
    show === true && (
      <div className="relative z-10">
        <div
          transition
          className="fixed inset-0 bg-gray-700 bg-opacity-50 transition-opacity data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in"
        />

        <div className="fixed inset-0 z-10 w-screen overflow-y-auto">
          <div className="flex min-h-full items-end justify-center p-4 text-center sm:items-center sm:p-0">
            <div
              transition
              className="relative transform overflow-hidden rounded-lg bg-white text-left shadow-xl transition-all data-[closed]:translate-y-4 data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in sm:my-8 sm:w-full sm:max-w-lg data-[closed]:sm:translate-y-0 data-[closed]:sm:scale-95"
            >
              <div className="bg-white px-4 pb-4 pt-5 sm:p-6 sm:pb-4">
                <div className="sm:flex sm:items-start">
                  <div className="mt-3 text-center sm:ml-4 sm:mt-0 sm:text-left">
                    <h1
                      as="h3"
                      className="text-2xl font-semibold leading-6 text-gray-900"
                    >
                      Confirm duplication with this merchant?
                    </h1>
                    <div className="mt-2">
                      <p className="text-sm text-gray-500">
                        Please enter a new email address for the new branch
                        merchant. Please keep it mind it will also duplicate the
                        products.
                      </p>
                    </div>
                    <div>
                      <input
                        type="email"
                        placeholder="Enter new merchant email"
                        value={newEmail}
                        onChange={(e) => setNewEmail(e.target.value)}
                        className="border my-2 rounded-lg border-gray-300 px-2.5 py-2 w-full outline-none"
                      />
                    </div>
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 px-4 py-3 sm:flex sm:flex-row-reverse sm:px-6">
                <button
                  type="button"
                  onClick={duplicateMerchant}
                  className="inline-flex w-full justify-center rounded-md bg-yellow-600 px-3 py-2 text-sm font-semibold text-white shadow-sm hover:bg-red-500 sm:ml-3 sm:w-auto"
                >
                  Continue
                </button>
                <button
                  type="button"
                  data-autofocus
                  onClick={() => showModaal(false)}
                  className="mt-3 inline-flex w-full justify-center rounded-md bg-white px-3 py-2 text-sm font-semibold text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 hover:bg-gray-50 sm:mt-0 sm:w-auto"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    )
  );
}

export function Modal2({ show, showModaal, storedUser }) {
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [gene, setGene] = useState(false);
  const [reportlink, serreporLink] = useState(null);

  const handleStartDateChange = (e) => {
    setStartDate(e.target.value);
    serreporLink(null);

    // Optionally, you can reset end date if it is earlier than start date
    if (endDate && e.target.value > endDate) {
      setEndDate("");
    }
  };

  const handleEndDateChange = (e) => {
    setEndDate(e.target.value);
    serreporLink(null);
  };

  const generateAdminRep = async () => {
    if (startDate && endDate) {
      setGene(true);
      try {
        const response = await axios.get(
          `https://kiapifers-dlver.cloud/report/payment/index.php?=&startingDate=${startDate}&endDate=${endDate}`
        );

        setGene(false);
        console.log(response);
        const maluma = response.data;
        if (maluma.success) {
          serreporLink(maluma.downloadLink);
        }
      } catch (e) {
        console.log(e.error);
        setGene(false);
      }
    }
  };

  const downloadFile = () => {
    if (!reportlink) return;

    // Create a temporary <a> element and trigger a download
    const link = document.createElement("a");
    link.href = reportlink;

    console.log(reportlink);

    // Optionally set a download attribute with a filename
    link.download = reportlink.split("/").pop(); // Use the filename from the URL
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    serreporLink(null);
  };

  return (
    show === true && (
      <div className="relative z-10">
        <div
          transition
          className="fixed inset-0 bg-gray-700 bg-opacity-50 transition-opacity data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in"
        />

        <div className="fixed inset-0 z-10 w-screen overflow-y-auto">
          <div className="flex min-h-full items-end justify-center p-4 text-center sm:items-center sm:p-0">
            <div
              transition
              className="relative transform overflow-hidden rounded-lg bg-white text-left shadow-xl transition-all data-[closed]:translate-y-4 data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in sm:my-8 sm:w-full sm:max-w-lg data-[closed]:sm:translate-y-0 data-[closed]:sm:scale-95"
            >
              <button
                type="button"
                data-autofocus
                onClick={() => showModaal(false)}
                className="absolute top-2 right-2 mt-3 inline-flex justify-center rounded-full bg-white p-2 text-sm font-semibold text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 hover:bg-gray-50 sm:mt-0 sm:w-auto"
              >
                <CloseIcon c="#404040" w="18" h="18" />
              </button>
              <div className="bg-white px-4 pb-4 pt-5 sm:p-6 sm:pb-4">
                <div className="">
                  <div className="mt-3 text-center  sm:mt-0 sm:text-left">
                    <h1
                      as="h3"
                      className="text-xl font-semibold leading-6 text-gray-900"
                    >
                      Generate Report
                    </h1>
                    <div className="mt-2">
                      <p className="text-sm text-gray-500">
                        Select custom date for your reporting.
                      </p>
                    </div>
                    <div className="py-4 flex justify-start items-center space-x-2 w-full">
                      <div className="w-full">
                        <p className="font-medium text-sm text-gray-600 py-1.5">
                          From
                        </p>
                        <input
                          id="reporting-start"
                          name="reporting-start"
                          type="date"
                          className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                          value={startDate}
                          onChange={handleStartDateChange}
                        />
                      </div>
                      <div className="w-full">
                        <p className="font-medium text-sm text-gray-600 py-1.5">
                          To
                        </p>
                        <input
                          id="reporting-end"
                          name="reporting-end"
                          type="date"
                          value={endDate}
                          onChange={handleEndDateChange}
                          min={startDate} // Ensure end date is no
                          className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 px-4 py-3 sm:flex sm:flex-row-reverse sm:px-6">
                {reportlink && (
                  <button
                    type="button"
                    onClick={downloadFile}
                    className="mx-2 inline-flex w-full justify-center rounded-md bg-white text-gray-600 border border-gray-300 shadow-lg  px-3 py-2 text-sm font-semibold hover:text-white shadow-sm hover:bg-red-500 sm:ml-3 sm:w-auto"
                  >
                    Download CSV
                  </button>
                )}

                {gene ? (
                  <div className="ml-4 mt-3 inline-flex w-full justify-center rounded-md bg-white px-3 py-2 text-sm font-semibold text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 hover:bg-gray-50 sm:mt-0 sm:w-auto">
                    <div className="w-8 h-8 rounded-full border-4 border-red-500 border-t-transparent animate-spin"></div>
                  </div>
                ) : (
                  startDate &&
                  endDate && (
                    <button
                      type="button"
                      onClick={generateAdminRep}
                      className="inline-flex w-full justify-center rounded-md bg-yellow-600 px-3 py-2 text-sm font-semibold text-white shadow-sm hover:bg-red-500 sm:ml-3 sm:w-auto"
                    >
                      Request Report
                    </button>
                  )
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    )
  );
}

export function Modal3({
  show,
  showModal,
  pickMe,
  handleStatusChange,
  handlePreparation,
}) {
  const [timee, sethjbb] = useState("");
  const [selecttimee, setNA] = useState(false);

  const hghd = (ed) => {
    if (ed != "Select Time") {
      sethjbb(ed);
      handlePreparation(pickMe, ed);
      setNA(true);
    }
  };

  return (
    show === true && (
      <div className="relative z-50">
        <div
          transition
          className="fixed inset-0 bg-gray-700 bg-opacity-50 transition-opacity data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in"
        />

        <div className="fixed inset-0 z-10 w-screen overflow-y-auto">
          <div className="flex min-h-full items-end justify-center p-4 text-center sm:items-center sm:p-0">
            <div
              transition
              className="relative transform overflow-hidden rounded-lg bg-white text-left shadow-xl transition-all data-[closed]:translate-y-4 data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in sm:my-8 sm:w-full sm:max-w-lg data-[closed]:sm:translate-y-0 data-[closed]:sm:scale-95"
            >
              <button
                type="button"
                data-autofocus
                onClick={() => showModal(false)}
                className="absolute top-2 right-2 mt-3 inline-flex justify-center rounded-full bg-white p-2 text-sm font-semibold text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 hover:bg-gray-50 sm:mt-0 sm:w-auto"
              >
                <CloseIcon c="#404040" w="18" h="18" />
              </button>
              <div className="bg-white px-4 pb-4 pt-5 sm:p-6 sm:pb-4">
                <div className="">
                  <div className="mt-3 text-center  sm:mt-0 sm:text-left">
                    <h1
                      as="h3"
                      className="text-xl font-semibold leading-6 text-gray-900"
                    >
                      Order for #{pickMe}
                    </h1>
                    <div className="mt-2">
                      <p className="text-sm text-gray-500">
                        Select Preparation Time
                      </p>
                    </div>
                    <div className="mt-2.5 border-2 p- border-gray-300 rounded-xl">
                      <select
                        value={timee}
                        onChange={(e) => hghd(e.target.value)}
                        className="bg-transparent text-lg font-mediumrounded-xl outline-none border-none p-2 w-full"
                      >
                        <option className="text-gray-300">Select Time</option>
                        <option>10mins - 20mins</option>
                        <option>10mins - 30mins</option>
                        <option>20mins - 30mins</option>
                        <option>35mins - 45mins</option>
                      </select>
                    </div>
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 px-4 py-3 sm:flex sm:flex-row-reverse sm:px-6">
                {selecttimee && (
                  <button
                    className="bg-red-500 hover:bg-red-600 w-48  px-2.5 py-1.5 shadow-sm text-white text-lg rounded-lg"
                    onClick={() => handleStatusChange(pickMe, "Accepted")}
                  >
                    Confirm Accept
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    )
  );
}
