import axios from 'axios';


export const validateEmail = email => {
const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
return re.test(email);
};


export function formatMoney(value) {
    // Divide the value by 100 to place the decimal point correctly
    const moneyValue = value;
  
    // Format to Philippine Peso with two decimal places
    return moneyValue.toLocaleString('fil-PH', {
      style: 'currency',
      currency: 'PHP',
      minimumFractionDigits: 2,
      maximumFractionDigits: 5,
    });
  }
  

export const SessionCheck = async (token) =>{
const api = process.env.REACT_APP_AUTH_API;
try {
const response = await axios.post(api, { token });
const data = response.data;
if (data.success) {
return data.user;
} else {
//
return data.error;

}

}catch (err) {
return err;
}
}

