const ModalLocation = ({
  setAddress1,
  setAddress2,
  setCoord1,
  setCoord2,
  selectMode,
  setModal,
}) => {
  const [locations, setLocations] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [filteredLocations, setFilteredLocations] = useState([]);

  useEffect(() => {
    const fetchLocation = async () => {
      try {
        const response = await axios.post(
          "https://kiefers-app.com/gen-polly/puerto.php",
          {
            access: null,
          }
        );

        const alLocation = response.data.data;
        setLocations(alLocation);
        setFilteredLocations(alLocation);
      } catch (e) {
        console.log(e);
      }
    };

    fetchLocation();
  }, [setFilteredLocations, setLocations]);

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
    if (e.target.value === "") {
      setFilteredLocations(locations);
    } else {
      const filtered = locations.filter((location) =>
        location.Locations.toLowerCase().includes(e.target.value.toLowerCase())
      );
      setFilteredLocations(filtered);
    }
  };

  const chooseLocation = (loc) => {
    if (selectMode === "PICK") {
      const ll = loc.Lat + "," + loc.Lng;
      setCoord1(ll);
      setAddress1(loc.Locations);
    } else {
      const kk = loc.Lat + "," + loc.Lng;
      setAddress2(loc.Locations);
      setCoord2(kk);
    }
    setModal(false);
  };

  return (
    <div className="relative z-10">
      <div
        transition
        className="fixed inset-0 bg-transparent transition-opacity data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in"
      />

      <div className="fixed inset-0 z-10 w-screen overflow-y-auto">
        <div className="flex min-h-full items-end justify-center p-4 text-center sm:items-center sm:p-0">
          <div className="relative transform overflow-hidden rounded-lg bg-white text-left shadow-xl transition-all data-[closed]:translate-y-4 data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in sm:my-8 sm:w-full sm:max-w-lg data-[closed]:sm:translate-y-0 data-[closed]:sm:scale-95">
            <div className="bg-white px-4 pb-4 pt-5 sm:p-6 sm:pb-4">
              <div
                onClick={() => setModal(false)}
                className="cursor-pointer bg-gray-200 rounded-full p-1.5 z-40 absolute top-2 right-2"
              >
                <CloseIcon c="#404040" w="25" h="25" />
              </div>
              <div className="w-full">
                <div className="mt-3 text-center sm:ml-4 sm:mt-0 sm:text-left">
                  <h1
                    as="h3"
                    className="text-base font-semibold leading-6 text-gray-900"
                  >
                    {selectMode === "PICK"
                      ? "Select Pickup Location"
                      : "Select Drop Location"}
                  </h1>
                  <div className="mt-2">
                    <div className="relative w-full my-2.5">
                      <label
                        for="search"
                        className="absolute bg-white left-4 -top-2 text-xs text-blue-500 font-medium"
                      >
                        Powered by OTW
                      </label>
                      <input
                        id="search"
                        value={searchTerm}
                        onChange={handleSearch}
                        name="search"
                        autoComplete="off"
                        type="name"
                        className="w-full p-2.5 border border-gray-300 rounded-xl outline-none"
                      ></input>
                    </div>
                    <div className="h-48 overflow-y-auto">
                      <ul>
                        {filteredLocations.map((location, index) => (
                          <li
                            key={index}
                            onClick={() => chooseLocation(location)}
                            className="cursor-pointer py-1.5 border-b border-gray-300"
                          >
                            <p className="font-medium">{location.Locations}</p>
                            <p className="text-xs text-gray-500">
                              {location.Lat},{location.Lng}
                            </p>
                          </li>
                        ))}
                      </ul>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

