import axios from "axios";
import React, { useEffect, useState } from "react";
import {
  Button1,
  ButtonAdd,
  ButtonWithIcon,
  LoadingButton,
} from "../components/button";
import {
  ArrowLeftBig,
  BookMark,
  BurgerIcon,
  NextIcon,
  PrevIcon,
  SettingsIcon,
} from "../components/icons";
import { Loader } from "../components/loader";
import { BigGreetingsTitle } from "../components/title";
import { Toast2 } from "../components/toast";
import { Tooltip5 } from "../components/tooltip";

const LoadPartners = ({ ManageStore, openStore }) => {
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const [currentItems, setCurrentItems] = useState([]);
  // const allpartners = NearbyStore();
  const [allpartners, setPartners] = useState([]);
  useEffect(() => {
    const fetchPartners = async () => {
      try {
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/user/pullusers/",
          {
            access: null,
          }
        );

        const alldata = response.data;

        if (alldata.status === "success") {
          // setPartners(alldata.users);

          // Apply pagination logic
          const indexOfLastItem = currentPage * itemsPerPage;
          const indexOfFirstItem = indexOfLastItem - itemsPerPage;
          const paginatedItems = alldata.users.slice(
            indexOfFirstItem,
            indexOfLastItem
          );
          console.log("users: ", alldata.users);
          setCurrentItems(paginatedItems);
          setPartners(paginatedItems);
        }
      } catch (e) {
        console.log(e);
      }
    };

    fetchPartners();
  }, [setPartners, currentPage]);

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  const ReturnSelectedLocation = (locationsString) => {
    let locations = [];
    try {
      if (locationsString !== "N/A") {
        locations = JSON.parse(locationsString);
      }
    } catch (error) {
      console.error("Invalid JSON:", error);
      // Handle the error or set a default value
      locations = [];
    }

    const selectedLocation = locations.find((location) => location.selected);
    const selectedLocationName = selectedLocation
      ? selectedLocation.name
      : "No selected location";
    return selectedLocationName;
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  const filteredPartners = allpartners.filter((partner) =>
    partner.Email.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const formatMoney = (amount) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "PHP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  const [decryptedBalances, setDecryptedBalances] = useState({});

  const checkPasswordX = async (riderID, passX) => {
    try {
      const response = await axios.post("https://kiefers-app.com/token/", {
        private: 1,
        secret: passX,
      });

      //console.log(response.data);
      if (response.data.status === "ok") {
        setDecryptedBalances((prevState) => ({
          ...prevState,
          [riderID]: formatMoney(response.data.message),
        }));
      }
    } catch (e) {
      console.log(e);
    }
  };

  return (
    <div>
      <div className="absolute top-2 left-14 right-3 max-w-80 sm:top-6 sm:w-80 sm:left-40">
        <input
          type="text"
          placeholder="Search user.."
          value={searchQuery}
          onChange={handleSearchChange}
          className="p-2 border rounded-xl w-full outline-none"
        />
      </div>

      <section className="rounded-t-xl max-h-[85vh] bg-white overflow-x-auto w-full">
        <table className="rounded-t-xl table-auto border-collapse whitespace-nowrap w-full ">
          <thead className="w-full sticky top-0 bg-[#ff1616] p-4 rounded-t-xl border dark:border-gray-700 z-50">
            <tr className="leading-none  z-50 snap-center p-4">
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Full Name
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Newsletter
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Address
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Email
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Status
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Wallet
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Contact Number
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Referral Code
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Joined
              </th>
              <th className="text-white text-center relative py-2.5 px-6 font-normal">
                Manage
              </th>
            </tr>
          </thead>
          <tbody className="bg-white">
            {filteredPartners.map((store) => (
              <tr
                onClick={() => ManageStore(store)}
                className="hover:bg-red-50 border border-gray-300"
                key={store.ID}
              >
                <td className="text-center px-6">{store.FirstName}</td>
                <td className=" text-center px-6">
                  <div className="flex justify-center items-center space-x-2">
                    <p className="mx-0.5">
                      {store.Newsletter == "1" ? (
                        <div className="flex justify-center items-center space-x-2">
                          <BookMark c="#f59e0b" h="15" w="15" />
                          <p className="bg-slate-100 px-2 py-0.5 rounded-lg">
                            Subscribed
                          </p>
                        </div>
                      ) : (
                        <p className="text-gray-300">Not interested</p>
                      )}
                    </p>
                  </div>
                </td>
                <td className="text-left">
                  <div className="w-56 truncate px-2.5 text-left">
                    {ReturnSelectedLocation(store.Address)}
                  </div>
                </td>

                <td className="text-left">
                  <p className="px-2.5 underline text-gray-400">
                    {store.Email}
                  </p>
                </td>
                <td className="text-center">
                  <div
                    className={`${
                      store.Status === "Verified"
                        ? "bg-green-500 text-white"
                        : "bg-slate-200"
                    } px-2 py-0.5 mx-2.5 rounded-lg `}
                  >
                    {store.Status}
                  </div>
                </td>
                <td className="cursor-pointer mx-8 px-2.5">
                  <Tooltip5 text="Click to decrypt the balance.">
                    <button
                      className="w-48 truncate font-mono text-center"
                      onClick={() => checkPasswordX(store.ID, store.Wallet)}
                    >
                      {decryptedBalances[store.ID] || store.Wallet}
                    </button>
                  </Tooltip5>
                </td>
                <td className="text-center px-4">{store.M_Number}</td>
                <td className="text-center px-4">{store.Referral}</td>
                <td className="text-center px-4">{store.Created}</td>
                <td className="text-center px-6 py-2.5">
                  <ButtonWithIcon
                    press={() => ManageStore(store)}
                    children={<SettingsIcon c="#dc2626" w="18" h="18" />}
                    title="Manage"
                  />
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {allpartners.length === 0 && (
          <div className="h-96 flex justify-center items-center p-8 w-full">
            <Loader />
          </div>
        )}
      </section>

      {filteredPartners.length > 0 && (
        <div className={`flex justify-start p-4 items-center space-x-2`}>
          <button
            className={`${
              currentPage === 1 ? "bg-gray-300" : "bg-red-500"
            } text-white rounded-lg px-2.5 py-2`}
            onClick={() => handlePageChange(currentPage - 1)}
            disabled={currentPage === 1}
          >
            <PrevIcon c="#f1f1f1" w="20" h="20" />
          </button>
          <div className="border border-gray-300 rounded-lg px-2.5 py-2 text-gray-500">
            {currentPage}
          </div>
          <button
            className={`${
              currentItems.length < itemsPerPage ? "bg-gray-300" : "bg-red-500"
            } text-white rounded-lg px-2.5 py-2`}
            onClick={() => handlePageChange(currentPage + 1)}
            disabled={currentItems.length < itemsPerPage}
          >
            <NextIcon c="#f1f1f1" w="20" h="20" />
          </button>
        </div>
      )}
    </div>
  );
};

const CreateMerchant = ({ HereMerchant }) => {
  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setTimeout(() => {
      setShow("hidden");
    }, 5000);
  };

  if (HereMerchant === null) {
    var HereMerchant = [];
  }

  const [formData, setFormData] = useState({
    username: HereMerchant.FirstName || "",
    phone: HereMerchant.M_Number || "",
    status: HereMerchant.Status || "Inactive",
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData({
      ...formData,
      [name]: type === "checkbox" ? checked : value,
    });
  };

  const validate = () => {
    const newErrors = {};

    if (!formData.username) newErrors.username = "Full name is required";
    if (!formData.phone) newErrors.phone = "Phone number is required";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const [loading, setLoading] = useState(false);
  const [loading1, setLoading1] = useState(false);
  const [loading2, setLoading2] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    const data = new FormData();
    for (const key in formData) {
      data.append(key, formData[key]);
    }

    try {
      setLoading(true);
      const boday = {
        target: HereMerchant.Email,
        target_column: "Status",
        new_value: formData.status,
      };

      var api = "https://kiapifers-dlver.cloud/user/update/";

      const response = await axios.post(api, boday, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      console.log(response.data);
      setLoading(false);
      showAlert(
        HereMerchant === null || HereMerchant.length === 0
          ? "Successfully Added!"
          : "Updated!"
      );
    } catch (error) {
      console.error(error);
      showAlert("Please try again. Error!");
      setLoading(false);
    }
  };

  const saveNumber = async (m) => {
    try {
      if (m === 1) {
        setLoading1(true);
        var boday = {
          target: HereMerchant.Email,
          target_column: "M_Number",
          new_value: formData.phone,
        };
      } else if (m === 2) {
        setLoading2(true);
        var boday = {
          target: HereMerchant.Email,
          target_column: "FirstName",
          new_value: formData.username,
        };
      }

      var api = "https://kiapifers-dlver.cloud/user/update/";

      const response = await axios.post(api, boday, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      setLoading1(false);
      setLoading2(false);
      showAlert("Updated!");
    } catch (e) {
      console.log(e);
    }
  };

  return (
    <form className="px-2.5" onSubmit={handleSubmit}>
      <div className="space-y-12">
        <div className="border-b border-gray-900/10 pb-12">
          <h2 className="text-base font-semibold leading-7 text-gray-900">
            Personal Information
          </h2>
          <p className="mt-1 text-sm leading-6 text-gray-600">
            This information needs an{" "}
            <span className="text-red-500 font-medium">internal review</span>.
          </p>

          <div className="mt-10 grid grid-cols-1 gap-x-6 gap-y-8 sm:grid-cols-6">
            <div className="sm:col-span-3">
              <label
                htmlFor="username"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Customer Full Name
              </label>
              <div className="mt-2 flex space-x-2">
                <div className="flex rounded-md shadow-sm ring-1 ring-inset ring-gray-300 outline-none sm:max-w-md">
                  <span className="flex select-none items-center pl-3 text-gray-500 sm:text-sm">
                    kiefersdelivery.com/
                  </span>
                  <input
                    id="username"
                    name="username"
                    type="text"
                    placeholder="Juan Dela Cruz"
                    autoComplete="username"
                    maxLength={100}
                    className="block flex-1 border-0 bg-transparent outline-none py-1.5 pl-1 text-gray-900 placeholder:text-gray-400 sm:text-sm sm:leading-6"
                    value={formData.username}
                    onChange={handleChange}
                  />
                </div>
                {loading2 ? (
                  <LoadingButton />
                ) : (
                  <button
                    type="button"
                    onClick={() => saveNumber(2)}
                    className="ml-2.5 bg-[#ff1616] px-2.5 py-1.5 text-white rounded-lg"
                  >
                    Save
                  </button>
                )}
              </div>
              {errors.username && (
                <p className="text-red-500 text-sm">{errors.username}</p>
              )}
            </div>

            <div className="sm:col-span-3">
              <label
                htmlFor="phone"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Contact Number
              </label>
              <div className="mt-2 flex justify-start space-x-2.5">
                <input
                  id="phone"
                  name="phone"
                  type="text"
                  maxLength={11}
                  className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2 outline-none sm:text-sm sm:leading-6"
                  value={formData.phone}
                  onChange={handleChange}
                />
                {loading1 ? (
                  <LoadingButton />
                ) : (
                  <button
                    type="button"
                    onClick={() => saveNumber(1)}
                    className="bg-[#ff1616] px-2.5 py-1.5 text-white rounded-lg"
                  >
                    Save
                  </button>
                )}
              </div>
              {errors.phone && (
                <p className="text-red-500 text-sm">{errors.phone}</p>
              )}
            </div>

            <div className="sm:col-span-4">
              <div className="flex space-x-2.5 justify-start items-end w-1/2">
                <div className="w-full">
                  <label
                    htmlFor="status"
                    className="block text-sm font-medium leading-6 text-gray-900"
                  >
                    Status
                  </label>
                  <div className="mt-2">
                    <select
                      id="status"
                      name="status"
                      className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                      value={formData.status}
                      onChange={handleChange}
                    >
                      <option value="Unverified">Unverified</option>
                      <option value="Verified">Verified</option>
                      <option value="Blocked">Block this user</option>
                    </select>
                  </div>
                </div>

                <div>
                  {loading ? (
                    <LoadingButton />
                  ) : (
                    <button
                      type="submit"
                      className="w-auto px-2 py-1.5 rounded-md bg-red-600  text-white shadow-sm hover:bg-[#ff1616] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-600"
                    >
                      Update
                    </button>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <Toast2 visible={errorShow} message={errormsg} />
    </form>
  );
};

function UsersPage({ setSideMenuOpen, activeSideMenu }) {
  const [activeScreen, setAScreen] = useState("TABLE"); // Default screen

  const changeView = (screen) => {
    setAScreen(screen);
  };

  const back2Merchant = () => {
    setAScreen("TABLE");
    setManage(null);
  };

  const [HereMerchant, setManage] = useState(null);
  const ManageStore = (it) => {
    setAScreen("CREATE");
    setManage(it);
  };

  const [openData, setOpenData] = useState([]);
  const openStore = (store) => {
    setAScreen("LOAD");
    setOpenData(store);
  };

  const [StoreProduct, SetStoreProduct] = useState([]);
  const [editProduct, setEditProduct] = useState([]);

  const AddProduct = () => {
    setEditProduct([]);
    setAScreen("ADD");
  };

  const EditNga = () => {
    setAScreen("ADD");
  };

  const renderScreen = () => {
    switch (activeScreen) {
      case "CREATE":
        return <CreateMerchant HereMerchant={HereMerchant} />;
      default:
        return <LoadPartners openStore={openStore} ManageStore={ManageStore} />;
    }
  };

  return (
    <div className="bg-white">
      <nav className="block  lg:hidden bg-red-500 top-2 h-14 shadow-xl w-full">
        <button
          onClick={() => setSideMenuOpen(!activeSideMenu)}
          className="block lg:hidden absolute top-2.5 left-2 bg-white p-2 rounded-lg shadow-xl"
        >
          <BurgerIcon c="#dc2626" w={20} h={20} />
        </button>
      </nav>
      <div className="p-4">
        <div className="flex justify-between items-center">
          <div className="my-4 flex justify-start space-x-2.5 items-center">
            {activeScreen === "CREATE" && (
              <div onClick={back2Merchant} className="cursor-pointer">
                <ArrowLeftBig c="#404040" h="20" w="20" />
              </div>
            )}
            <BigGreetingsTitle
              text={
                activeScreen === "LOAD"
                  ? openData.StoreName
                  : activeScreen === "ADD"
                  ? "Add Product"
                  : "App Users"
              }
            />
            <div className="cursor-pointer bg-gray-300 w-px h-8"></div>
          </div>
          <div className="hidden flex justify-start items-center space-x-2">
            {activeScreen === "CREATE" ? (
              <Button1 click={back2Merchant} text="Back to Riders" />
            ) : (
              <>
                {activeScreen === "LOAD" ? (
                  <ButtonAdd text="Add Product" click={AddProduct} />
                ) : activeScreen === "ADD" ? (
                  <Button1 click={() => openStore(openData)} text="Close" />
                ) : (
                  <ButtonAdd
                    click={() => changeView("CREATE")}
                    text="Create Rider"
                  />
                )}
              </>
            )}
          </div>
        </div>

        {renderScreen()}
      </div>
    </div>
  );
}

export default UsersPage;
