import axios from "axios";
import { doc, getFirestore, serverTimestamp, setDoc } from "firebase/firestore";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { ButtonGo, LoadingButton } from "../components/button";
import { EmailTextbox, PasswordTextbox } from "../components/inputs";
import { MediumLogo } from "../components/logo";
import { BigGreetingsTitle, SmallTitleChild } from "../components/title";
import { Toast1 } from "../components/toast";
import { validateEmail } from "../config/functions";

function LoginPage({ setPrivData, onLogin }) {
  const navigate = useNavigate();
  const [remember, setRemember] = useState(true);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const [startLog, setStart] = useState(false);
  const [token, setToken] = useState(null);

  const db = getFirestore();

  async function handleLogin(userEmail, pic) {
    try {
      await setDoc(doc(db, "onlineUsers", userEmail), {
        email: userEmail,
        loginTime: serverTimestamp(),
        image: pic,
      });
    } catch (error) {
      console.error("Error adding document: ", error);
    }
  }

  useEffect(() => {
    const rem = localStorage.getItem("keepers");
    if (rem) {
      setEmail(rem);
    }
  }, [setEmail]);

  const getEmail = (e) => {
    setEmail(e.target.value);
  };

  const getPass = (e) => {
    setPassword(e.target.value);
  };

  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setStart(false);
    setTimeout(() => {
      setShow("hidden");
    }, 3000);
  };

  const SignInCheck = async () => {
    //kiapifers-dlver.cloud/merchant/merchantemail/index.php?Email=burgerbliss@gmail.com
    if (email.trim() == "" || password.trim() == "") {
      return;
    }

    if (!validateEmail(email)) {
      showAlert("Invalid email format. Please use your valid email address.");
      return;
    }

    setStart(true);

    const api = process.env.REACT_APP_LOGIN_API;

    try {
      const response = await axios.post(api, { email, password });
      const { token } = response.data;
      const data = response.data;
      if (data.success) {
        setToken(data.token);
        setStart(false);

        // Save token and user data in local storage
        localStorage.setItem("token", token);
        const user = {
          account: email,
          access: password,
          session: token,
        };

        const response2 = await axios.get(
          "https://kiapifers-dlver.cloud/adminconsole/getadmin/",
          {
            params: { Email: email },
          }
        );

        setPrivData(response2.data.data);
        const mypic = response2.data.data.Profile;

        if (response2.data.data.Status === "Inactive") {
          showAlert(
            "This account is not currently authorized to access this platform. Please reach out to your internal administrators for assistance."
          );
          return;
        }

        localStorage.setItem("user", JSON.stringify(user));

        if (remember) {
          localStorage.setItem("keepers", email);
        }
        // Call the onLogin function to update the parent component's state
        const fb = await handleLogin(email, mypic);
        onLogin(user);

        navigate("/home");
      } else {
        //check if merchant
        //kiapifers-dlver.cloud/merchant/merchantemail/index.php?Email=burgerbliss@gmail.com

        const responseMerchant = await axios.get(
          "https://kiapifers-dlver.cloud/merchant/merchantemail/index.php",
          {
            params: { Email: email },
          }
        );

        const tokee = responseMerchant.data.token;
        if (responseMerchant.data.success) {
          const passk = responseMerchant.data.password;

          //check password
          const responsePasss = await axios.post(
            "https://kiefers-app.com/token/",
            {
              private: 1,
              secret: passk,
            }
          );

          if (responsePasss.data.message === password) {
            //get info
            const responseMerchantInfo = await axios.get(
              "https://kiapifers-dlver.cloud/merchant/getmerchant/",
              {
                params: { Email: email },
              }
            );

            if (
              responseMerchantInfo.data.data[0].Status === "Active" ||
              responseMerchantInfo.data.data[0].Status === "Pre-Active"
            ) {
              setPrivData(responseMerchantInfo.data.data[0]);

              setToken(tokee);
              setStart(false);

              // Save token and user data in local storage
              localStorage.setItem("token", tokee);
              const user = {
                account: email,
                access: password,
                session: tokee,
              };

              //allow
              localStorage.setItem("user", JSON.stringify(user));

              if (remember) {
                localStorage.setItem("keepers", email);
              }
              navigate("/home");
            } else {
              setToken(null);
              showAlert("Merchant account is inactive.");
              return;
            }
          } else {
            setToken(null);
            showAlert("Wrong password.");
            return;
          }
        } else {
          setToken(null);
          showAlert(
            "Somethings is wrong. Check your login credentials as well or contact us."
          );
          return;
        }
      }
    } catch (err) {
      showAlert("Please try again");
      return;
    }
  };

  useEffect(() => {
    const autoLogin = async () => {
      try {
        const storedUser = localStorage.getItem("user");
        if (storedUser) {
          const user = JSON.parse(storedUser);
          setEmail(user?.account);
          setPassword(user?.access);
          await SignInCheck();
        }
      } catch (error) {
        console.error("Error parsing user data:", error);
      }
    };

    autoLogin();
  }, [email]);

  const rememberDevice = () => {
    if (remember) {
      setRemember(false);
    } else {
      setRemember(true);
      //send post to local
    }
  };
  //console.log('Environment Variables:', process.env);
  const appVersion = process.env.REACT_APP_CONTROL_VERSION || "not Set";

  const handleKeyDown = (event) => {
    if (event.key === "Enter") {
      SignInCheck();
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-8 flex justify-center items-center bg-white h-screen">
      <>
        <div className="w-full lg:w-1/2 md:w-1/2  p-2.5 lg:px-12 md:px-12">
          <div className="flex justify-center items-center py-4">
            <MediumLogo />
          </div>
          <div className="text-center">
            <BigGreetingsTitle text="Welcome to Business Suite" />
          </div>
          <div className="space-y-2.5 mt-8">
            <EmailTextbox value={email} fun={getEmail} />
            <PasswordTextbox
              value={password}
              fun={getPass}
              handleKeyDown={handleKeyDown}
            />
          </div>
          <div
            onClick={rememberDevice}
            className="group cursor-pointer my-4 flex justify-start items-center space-x-2.5"
          >
            <div className="bg-red-100 group-hover:bg-red-200 p-2 w-6 h-6 rounded-md">
              {remember && (
                <div className="bg-[#ff1616] group-hover:bg-red-600 h-2 w-2 rounded-md"></div>
              )}
            </div>
            <p>Remember me</p>
          </div>
          <div>
            {startLog ? (
              <LoadingButton />
            ) : (
              <ButtonGo click={SignInCheck} text="Continue" />
            )}

            <div className="my-6"></div>
          </div>
          <div className="mt-14">
            <SmallTitleChild>
              This is an external tool exclusively for Kiefers only.
              <p>Version: {appVersion}</p>
            </SmallTitleChild>
          </div>
        </div>
      </>
      <Toast1 visible={errorShow} message={errormsg} />
    </div>
  );
}

export default LoginPage;
