import axios from "axios";
import React, { useEffect, useState } from "react";
import GCASH from "../assets/icons/gcash.png";
import MAYA from "../assets/icons/maya.png";
import {
  Button1,
  ButtonAdd,
  ButtonWithIcon,
  LoadingButton,
} from "../components/button";
import {
  AddIcon,
  ArrowLeftBig,
  BurgerIcon,
  CloseIcon,
  SettingsIcon,
} from "../components/icons";
import { Loader } from "../components/loader";
import { Modal2 } from "../components/modal";
import { BigGreetingsTitle } from "../components/title";
import { Toast2 } from "../components/toast";

const LoadPartners = ({ ManageStore, openStore }) => {
  // const allpartners = NearbyStore();
  const [allpartners, setPartners] = useState([]);
  useEffect(() => {
    const fetchPartners = async () => {
      try {
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/createpayment/pullpayment2/",
          {
            access: null,
          }
        );

        const alldata = response.data;

        if (alldata.status) {
          setPartners(alldata.payments);
        }
      } catch (e) {
        console.log(e);
      }
    };

    fetchPartners();
  }, [setPartners]);

  const formatMoney = (amount) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "PHP",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  return (
    <section className="rounded-t-xl max-h-[85vh] bg-white overflow-x-auto w-full">
      <table className="rounded-t-xl table-auto border-collapse whitespace-nowrap w-full">
        <thead className="sticky top-0 bg-[#ff1616] p-4 rounded-t-xl border dark:border-gray-700 relative w-full">
          <tr className="leading-none  z-50 snap-center p-4">
            <th className="text-white text-center relative p-2.5 font-normal">
              Booking ID
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Email
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Transaction ID
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Amount
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Provider
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Processed
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Status
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Manage
            </th>
          </tr>
        </thead>
        <tbody className="bg-white">
          {allpartners.map((store) => (
            <tr
              onClick={() => ManageStore(store)}
              className="hover:bg-red-50 border border-gray-300 "
              key={store.ID}
            >
              <td className="text-center ">
                <p className="w-48 truncate font-mono">{store.BookingID}</p>
              </td>

              <td className="text-center ">
                <p className="w-48 truncate underline text-gray-400">
                  {store.Email}
                </p>
              </td>

              <td className="text-center ">
                <p className="w-48 truncate font-mono">{store.TransactionID}</p>
              </td>

              <td className="text-left">
                <div className="text-center px-2.5">
                  {formatMoney(store.Amount)}
                </div>
              </td>

              <td className="text-center">
                <div>
                  {store.Provider === "GCASH" ? (
                    <div className="flex justify-center items-center">
                      <img src={GCASH} className="w-auto h-4" alt="GCASH" />
                    </div>
                  ) : store.Provider === "PAYMAYA" ? (
                    <div className="flex justify-center items-center">
                      <img src={MAYA} className="w-auto h-4" alt="PAYMAYA" />
                    </div>
                  ) : (
                    <p
                      className={
                        store.Provider === "GCASH"
                          ? "font-bold text-blue-500"
                          : "text-gray-600"
                      }
                    >
                      {store.Provider}
                    </p>
                  )}
                </div>
              </td>

              <td className="text-center text-sm w-48 px-4 text-gray-500">
                {store.Created}
              </td>

              <td className="text-center">
                <div className="flex justify-center items-center">
                  <div
                    className={`w-auto ${
                      store.Status === "Paid"
                        ? "bg-green-500 text-white"
                        : "bg-slate-200 text-gray-600"
                    } px-2 py-0.5 rounded-lg`}
                  >
                    {store.Status}
                  </div>
                </div>
              </td>

              <td className="text-center p-2.5">
                <div className="px-2.5">
                  <ButtonWithIcon
                    press={() => ManageStore(store)}
                    children={<SettingsIcon c="#dc2626" w="18" h="18" />}
                    title="Manage"
                  />
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {allpartners.length === 0 && (
        <div className="h-96 flex justify-center items-center p-8">
          <Loader />
        </div>
      )}
    </section>
  );
};

const CreateMerchant = ({ HereMerchant, openData, storedUser }) => {
  //console.log(HereMerchant);
  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setTimeout(() => {
      setShow("hidden");
    }, 5000);
  };

  if (HereMerchant === null) {
    var HereMerchant = [];
  }

  const [formData, setFormData] = useState({
    amount: HereMerchant.Amount || "0",
    provider: HereMerchant.Provider || "Cash on Delivery",
    status: HereMerchant.Status || "Inactive",
    rider: HereMerchant.Status || "",
    about: HereMerchant.Description || "",
    deliveryfee: HereMerchant.DeliveryFee || "",
    unitprice: HereMerchant.UnitPrice || "",
    servicefee: HereMerchant.ServiceFee || "",
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    //console.log(e.target)
    setFormData({
      ...formData,
      [name]: type === "checkbox" ? checked : value,
    });
  };

  const [markdown, setMarkdown] = useState(0);
  const [allrider, setRiders] = useState([]);
  const [allprod, setProducts] = useState([]);
  const [allpartners, setPartners] = useState([]);
  const [merchantEmail, setMerchantEmail] = useState([]);
  const [merchantName, setMerchantName] = useState([]);
  const [lockPay, setLock] = useState(false);
  const [paymentState, paymentStatus] = useState("Pending");

  useEffect(() => {
    const pullRider = async () => {
      try {
        //kiapifers-dlver.cloud/category/pullcategory/
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/rider/pullrider/",
          {
            access: null,
          }
        );

        const req_data = response.data.data;
        //console.log(req_data);
        setRiders(response.data.data);
      } catch (e) {
        console.log(e);
      }
    };

    const LoadALL = async () => {
      try {
        const cred1 = HereMerchant.Cart
          ? HereMerchant.Cart.split("-")[1].trim()
          : merchantEmail;
        const cred2 = HereMerchant.Cart
          ? HereMerchant.Cart.split("-")[0]
          : merchantName;
        setNewMerchant(HereMerchant.Cart || "");

        const response = await axios.get(
          `https://kiapifers-dlver.cloud/merchant/getmerchantproduct/?Email=${cred1}&StoreName=${cred2}`
        );
        var tempra = response.data.products;
        setProducts(response.data.products);
        if (HereMerchant.Cart) {
          var selected2 = (HereMerchant.Item || "")
            .split(",")
            .map((id) => id.trim())
            .map((id) =>
              response.data.products.find((food) => food.ProductID === id)
            )
            .filter(Boolean);
          setSelectedFoods(selected2);
        }
      } catch (e) {
        console.log(e);
      }
    };
    const fetchPartners = async () => {
      try {
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/merchant/pullmerchant/",
          {
            access: null,
          }
        );

        const alldata = response.data;

        if (alldata.success) {
          setPartners(alldata.data);
        }
      } catch (e) {
        console.log(e);
      }
    };

    const pullTransaction = async () => {
      try {
        const response = await axios.get(
          `https://kiapifers-dlver.cloud/transaction/gettransaction/?TransactionID=${HereMerchant.TransactionID}`,
          {
            access: null,
          }
        );
        setFormData({
          ...formData,
          rider: response.data.transactions[0].RiderID,
          unitprice: response.data.transactions[0].UnitPrice,
          deliveryfee: response.data.transactions[0].DeliveryFee,
          servicefee: response.data.transactions[0].ServiceFee,
        });
      } catch (e) {
        console.log(e);
      }
    };

    if (HereMerchant.PaymentLink) {
      setShowLink(true);
      setPaymentLink(HereMerchant.PaymentLink);
      setinv(HereMerchant.TransactionID);
      setLock(true);
      paymentStatus(HereMerchant.Status);
      pullTransaction();
    }

    console.log(HereMerchant);

    LoadALL();
    pullRider();
    fetchPartners();
  }, [
    setRiders,
    setProducts,
    setPartners,
    merchantEmail,
    merchantName,
    setLock,
    paymentStatus,
  ]);

  const ResetNga = () => {
    setFormData({
      amount: HereMerchant.Amount || "0",
      provider: HereMerchant.Provider || "Cash on Delivery",
      status: HereMerchant.Status || "Inactive",
      rider: HereMerchant.RiderID || "",
      about: HereMerchant.Description || "",
      deliveryfee: HereMerchant.DeliveryFee || "",
      unitprice: HereMerchant.UnitPrice || "",
      servicefee: HereMerchant.ServiceFee || "",
    });
    setCover(null);
    setUploadProgress(0);
  };

  const [selectedFoods, setSelectedFoods] = useState([]);
  const [newFood, setNewFood] = useState("");

  const [newMerchant, setNewMerchant] = useState("");

  const handleSelectFood = () => {
    const selectedProduct = newFood;
    const selectedFood = allprod.find(
      (food) => food.Product === selectedProduct
    );

    if (selectedFood) {
      const isAlreadySelected = selectedFoods.some(
        (food) => food.Product === selectedProduct
      );
      setSelectedFoods([...selectedFoods, selectedFood]);
      const totalPrice = selectedFoods.reduce(
        (sum, food) => sum + parseFloat(food.Price),
        0
      );
    }

    setNewFood("");
  };

  const formatMoney = (amount) => {
    return new Intl.NumberFormat("en-US").format(amount);
  };

  const commRATE = () => {
    const totalPrice2 = selectedFoods.reduce((sum, food) => {
      const priceToAdd =
        food.Discounted === "0" || food.Discounted === ""
          ? parseFloat(food.Price)
          : parseFloat(food.Discounted);
      const Ahd = sum + priceToAdd;
      return Math.round(Ahd);
    }, 0);

    setFormData({
      ...formData,
      unitprice: formatMoney(totalPrice2),
    });
  };

  const handleInputChange = (e) => {
    setNewFood(e.target.value);
  };

  const handleInputChangeMerchant = (e) => {
    setNewMerchant(e.target.value);

    const parts = e.target.value.split("-");
    if (parts.length > 1) {
      var hyuusd = parts[1].trim();
      setMerchantEmail(hyuusd);
    }

    // Find the selected merchant based on the value
    const selectedPartner = allpartners.find(
      (partner) => partner.Email === hyuusd
    );

    if (selectedPartner) {
      setMarkdown(parseInt(selectedPartner.Review) / 100);
      setFormData({
        ...formData,
        servicefee: selectedPartner.Review,
      });
    }

    setSelectedFoods([]);
    setProducts([]);
    const yusd = e.target.value.split("-")[0];
    setMerchantName(yusd);
    LoadALLSTORE(hyuusd, yusd, e.target.value);
  };

  const LoadALLSTORE = async (dat1, dat2, dat3) => {
    //setNewMerchant(dat3);
    try {
      const cred1 = dat1;
      const cred2 = dat2;

      const response = await axios.get(
        `https://kiapifers-dlver.cloud/merchant/getmerchantproduct/?Email=${cred1}&StoreName=${cred2}`
      );
      var tempra = response.data.products;
      setProducts(response.data.products);
    } catch (e) {
      console.log(e);
    }
  };

  const handleRemoveFood = (index) => {
    setSelectedFoods(selectedFoods.filter((_, i) => i !== index));
  };

  //====UPLOADING FILE
  const [cover, setCover] = useState(HereMerchant.Image || null);
  const [uploadProgress, setUploadProgress] = useState(0);

  const validate = () => {
    const newErrors = {};
    if (!formData.amount) newErrors.amount = "Amount is required";
    if (!formData.provider) newErrors.provider = "Provider is required";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const [loading, setLoading] = useState(false);
  const handleSubmit = async (e) => {
    e.preventDefault();
    //if (!validate()) return;

    const data = new FormData();
    for (const key in formData) {
      data.append(key, formData[key]);
    }

    const productIDs = selectedFoods.map((food) => food.ProductID);

    try {
      setLoading(true);

      var boday = {
        TransactionID: invo,
        RiderID: formData.rider,
      };

      var api = "https://kiapifers-dlver.cloud/createpayment/updatedynamic2/";
      if (HereMerchant === null || HereMerchant.length === 0) {
        api =
          "https://kiapifers-dlver.cloud/createpayment/manualpayment/create/";
        boday = {
          Email: storedUser.email,
          Amount: formData.amount,
          Provider: formData.provider,
          RiderID: formData.rider,
          Description: formData.about,
          ProductID: "N/A",
          Item: productIDs.join(", "),
          UnitPrice: formData.unitprice,
          DeliveryFee: formData.deliveryfee,
          ServiceFee: formData.servicefee,
          Discount: 0,
          Cart: newMerchant,
        };
      }

      setPyaprocvider(formData.provider);
      const response = await axios.post(api, boday, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      console.log(response.data);
      setLoading(false);
      showAlert(
        HereMerchant === null || HereMerchant.length === 0
          ? "Successfully Added!"
          : "Updated!"
      );
      if (formData.provider == "Cash On Delivery") {
        //COD
        showAlert(
          HereMerchant === null || HereMerchant.length === 0
            ? "Successfully Added!"
            : "Updated!"
        );
        ResetNga();
      } else {
        //need online payment
        if (response.data.status == "success") {
          setinv(response.data.TransactionID);
          setPaymentLink(response.data.PaymentLink);
          setShowLink(true);
        }
      }
    } catch (error) {
      console.error(error);
      showAlert("Please try again. Error!");
      setLoading(false);
    }
  };

  const [payprovider, setPyaprocvider] = useState(HereMerchant.Provider || "");
  const [paymentLink, setPaymentLink] = useState("");
  const [invo, setinv] = useState("N/A");
  const [showLink, setShowLink] = useState(false);

  const copyToClipboard = () => {
    navigator.clipboard
      .writeText(paymentLink)
      .then(() => {
        showAlert("Link copied to clipboard!");
      })
      .catch((err) => {
        showAlert("Failed to copy the link: ");
      });
  };

  const calculateRate = () => {
    const uniP = formData.unitprice;
    const deliP = formData.deliveryfee;
    const serP = parseInt(formData.servicefee) / 100;
    const totalPR = parseInt(uniP) * serP;
    const totalPR2 = totalPR + parseInt(deliP);
    const totalPR3 = totalPR2 + parseInt(uniP);
    setFormData({
      ...formData,
      amount: Math.round(totalPR3),
    });
  };

  const handleCheckStatus = async (e) => {
    setFormData({
      ...formData,
      status: e.target.value,
    });
    paymentStatus(e.target.value);
    try {
      const xdata = {
        TransactionID: invo,
        Status: e.target.value,
      };
      const response = await axios.post(
        "https://kiapifers-dlver.cloud/createpayment/updatepayment/",
        xdata,
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      showAlert("Payment status updated");
    } catch (e) {
      console.warn(e);
    }
  };

  return (
    <form className="px-2.5" onSubmit={handleSubmit}>
      <div className="space-y-12">
        <div className="border-b border-gray-900/10 pb-12">
          <h2 className="text-base font-semibold leading-7 text-gray-900">
            Payments Information
          </h2>
          <p className="mt-1 text-sm leading-6 text-gray-600">
            This information will be displayed in reporting so be careful what
            you inputs,{" "}
            <span className="text-red-500 font-medium">ask for a review</span>.
          </p>

          <div className="mt-10 grid grid-cols-1 gap-x-6 gap-y-8 sm:grid-cols-6">
            {showLink && (
              <div className="col-span-full">
                <div
                  className={`relative rounded-xl ${
                    paymentState === "Paid"
                      ? "bg-green-500 text-yellow-100"
                      : "bg-white text-red-500"
                  } py-2.5 px-4  border border-gray-300 shadow-md`}
                >
                  <img
                    src="https://kiefers-app.com/assets/celeb.svg"
                    className="w-full h-32 object-cover object-top"
                  />
                  <div
                    className={`mx-2 p-4 absolute top-0 right-0 left-0 bottom-0 ${
                      paymentState === "Paid" ? "bg-transparent" : "bg-white"
                    }`}
                  >
                    {paymentState == "Paid" ? (
                      <>
                        <h1 className="text-3xl font-normal my-1.5 text-white">
                          <span className="text-orange-200 font-medium">
                            &#8369;{formData.amount}
                          </span>
                          !! This payment is paid!
                        </h1>
                        <p className="text-md text-white">
                          See payment invoice{" "}
                          <span className="font-bold text-white">
                            {HereMerchant.Invoice}
                          </span>
                        </p>
                      </>
                    ) : (
                      <>
                        <h1 className="text-xl font-normal my-1.5 text-gray-600">
                          Payment Link for{" "}
                          <span className="font-bold text-gray-800">
                            {invo}
                          </span>
                        </h1>
                        <div className="flex justify-start space-x-2.5 items-center">
                          <p className="text-sm text-gray-500">
                            Generated payment link successfully for
                          </p>
                          <div>
                            {HereMerchant.Provider === "GCASH" ? (
                              <div>
                                <img
                                  src={GCASH}
                                  className="w-auto h-4"
                                  alt="GCASH"
                                />
                              </div>
                            ) : HereMerchant.Provider === "PAYMAYA" ? (
                              <div className="mt-2">
                                <img
                                  src={MAYA}
                                  className="w-auto h-4"
                                  alt="PAYMAYA"
                                />
                              </div>
                            ) : (
                              <p className="bg-yellow-500 text-sm text-white px-2 py-0.5 rounded-lg">
                                {payprovider}
                              </p>
                            )}
                          </div>
                        </div>
                      </>
                    )}

                    <div className="mt-1.5 flex items-start  w-full justify-between">
                      <a
                        href={paymentLink}
                        className={`w-full font-normal underline ${
                          paymentState === "Paid"
                            ? "text-white"
                            : "text-blue-500"
                        } text-sm`}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        {paymentLink}
                      </a>

                      <button
                        onClick={copyToClipboard}
                        className={`ml-4  ${
                          paymentState === "Paid" ? "bg-gray-800" : "bg-red-500"
                        } text-white py-1 px-2 rounded-lg`}
                      >
                        Copy
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            )}

            <div className="sm:col-span-2">
              <div>
                <label
                  htmlFor="amount"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Gross Amount
                </label>

                <div className="mt-2">
                  <div className="relative">
                    <div className="left-2 top-1 text-gray-600 font-normal absolute mb-0.5 text-lg">
                      &#8369;
                    </div>
                    <input
                      id="amount"
                      name="amount"
                      type="number"
                      min={0}
                      max={15000}
                      placeholder="Enter Amount"
                      className="block w-full rounded-md border-0 py-1.5 pl-5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                      value={formData.amount}
                      onChange={handleChange}
                      disabled={HereMerchant.length === 0 ? false : true}
                    />
                  </div>
                </div>
                {errors.amount && (
                  <p className="text-red-500 text-sm">{errors.amount}</p>
                )}
              </div>
            </div>

            <div className="sm:col-span-2">
              <label
                htmlFor="provider"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Provider
              </label>
              <div className="mt-2">
                <select
                  id="provider"
                  name="provider"
                  className=" block w-full rounded-md border-0 py-2 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                  onChange={handleChange}
                  value={formData.provider}
                  disabled={HereMerchant.length === 0 ? false : true}
                >
                  <option value="GCASH">GCash</option>
                  <option value="PAYMAYA">Paymaya</option>
                  <option value="Cash on Delivery">Cash on Delivery</option>
                </select>
              </div>
            </div>

            <div className="sm:col-span-2">
              <label
                htmlFor="rider"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Assigned Rider
              </label>
              <div className="mt-2">
                <select
                  id="rider"
                  name="rider"
                  className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                  value={formData.rider}
                  onChange={handleChange}
                >
                  <option value="">Select Assignee</option>
                  {allrider.map((categ) => (
                    <option key={categ.RiderID} value={categ.RiderID}>
                      {categ.FirstName}
                    </option>
                  ))}
                </select>
              </div>
              {errors.rider && (
                <p className="text-red-500 text-sm">{errors.rider}</p>
              )}
            </div>

            <div className="sm:col-span-2">
              <div>
                <label
                  htmlFor="amount"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Unit Price
                </label>
                <div className="mt-2">
                  <div className="relative">
                    <div className="left-2 top-1 text-gray-600 font-normal absolute mb-0.5 text-lg">
                      &#8369;
                    </div>
                    <input
                      id="unitprice"
                      name="unitprice"
                      type="unitprice"
                      min={0}
                      max={15000}
                      disabled={HereMerchant.length === 0 ? false : true}
                      placeholder="Enter Price"
                      className="block w-full rounded-md border-0 py-1.5 pl-5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                      value={formData.unitprice}
                      onChange={handleChange}
                    />
                  </div>
                </div>
                {errors.unitprice && (
                  <p className="text-red-500 text-sm">{errors.unitprice}</p>
                )}
              </div>
            </div>

            <div className="sm:col-span-2">
              <div>
                <label
                  htmlFor="deliveryfee"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Delivery Fee
                </label>
                <div className="mt-2">
                  <div className="relative">
                    <div className="left-2 top-1 text-gray-600 font-normal absolute mb-0.5 text-lg">
                      &#8369;
                    </div>
                    <input
                      id="deliveryfee"
                      name="deliveryfee"
                      type="deliveryfee"
                      min={0}
                      max={15000}
                      placeholder="Enter Amount"
                      className="block w-full rounded-md border-0 py-1.5 pl-5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                      value={formData.deliveryfee}
                      onChange={handleChange}
                      disabled={HereMerchant.length === 0 ? false : true}
                    />
                  </div>
                </div>
                {errors.deliveryfee && (
                  <p className="text-red-500 text-sm">{errors.deliveryfee}</p>
                )}
              </div>
            </div>

            <div className="sm:col-span-2">
              <div>
                <label
                  htmlFor="servicefee"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Service Fee
                </label>
                <div className="mt-2 flex justify-start space-x-1.5">
                  <div className="relative">
                    <div className="left-2 top-1 text-gray-600 font-normal absolute mb-0.5 text-lg">
                      %
                    </div>
                    <input
                      id="servicefee"
                      name="servicefee"
                      type="servicefee"
                      min={0}
                      max={15000}
                      placeholder="Enter Amount"
                      className="block w-full rounded-md border-0 py-1.5 pl-8 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                      value={formData.servicefee}
                      onChange={handleChange}
                      disabled={HereMerchant.length === 0 ? false : true}
                    />
                  </div>
                  <button
                    type="button"
                    onClick={calculateRate}
                    disabled={HereMerchant.length === 0 ? false : true}
                    class="rounded-lg text-white text-sm bg-red-100 hover:bg-red-500 px-2 py-1.5"
                  >
                    Calculate
                  </button>
                </div>
                {errors.servicefee && (
                  <p className="text-red-500 text-sm">{errors.servicefee}</p>
                )}
              </div>
            </div>

            {HereMerchant.Provider === "Cash on Delivery" && (
              <div className="sm:col-span-2">
                <label
                  htmlFor="status"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Payment Status
                </label>
                <div className="mt-2">
                  <select
                    id="status"
                    name="status"
                    className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                    value={formData.status}
                    onChange={handleCheckStatus}
                  >
                    <option value="Pending">Pending</option>
                    <option value="Paid">Paid</option>
                    <option value="Disputed">Disputed</option>
                  </select>
                </div>
              </div>
            )}

            <div className="col-span-full">
              <label
                htmlFor="about"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Description
              </label>
              <div className="mt-2">
                <textarea
                  id="about"
                  name="about"
                  rows={3}
                  maxLength={100}
                  className="block w-full rounded-md border-0 py-1.5 px-2.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 outline-none sm:text-sm sm:leading-6"
                  value={formData.about}
                  onChange={handleChange}
                />
              </div>
              {errors.about && (
                <p className="text-red-500 text-sm">{errors.about}</p>
              )}
              <p className="mt-3 text-sm leading-6 text-gray-600">
                Write a note for this payment.
              </p>
            </div>

            <div className="col-span-full">
              <div
                className={`flex flex-col sm:flex-row justify-between ${
                  lockPay === "Paid" ? "opacity-50 cursor-not-allowed" : ""
                } sm:items-center`}
              >
                <p className="font-medium text-lg">
                  Built-in Cart{" "}
                  <sup className="bg-yellow-500 text-sm text-white rounded-lg px-2 py-1.5">
                    BETA
                  </sup>
                </p>
                <div className="flex  flex-col sm:flex-row space-y-2.5 sm:justify-end sm:space-y-0 sm:space-x-2.5">
                  <input
                    list="merchant-app"
                    id="merchant-app-input"
                    value={newMerchant}
                    onChange={handleInputChangeMerchant}
                    placeholder="Select Merchant"
                    className="outline-none border border-gray-300 px-2.5 py-1.5 rounded-xl"
                    disabled={HereMerchant.length === 0 ? false : true}
                  />
                  <datalist id="merchant-app">
                    {allpartners.map((food, index) => (
                      <option
                        key={index}
                        value={`${food.StoreName} - ${food.Email}`}
                      />
                    ))}
                  </datalist>
                  <input
                    list="required-foods"
                    id="required-food-input"
                    value={newFood}
                    onChange={handleInputChange}
                    placeholder="Choose or type food"
                    autoComplete="off"
                    className="outline-none border border-gray-300 px-2.5 py-1.5 rounded-xl"
                    disabled={HereMerchant.length === 0 ? false : true}
                  />
                  <datalist id="required-foods">
                    {allprod.map((food, index) => (
                      <option key={index} value={food.Product} />
                    ))}
                  </datalist>
                  <div
                    onClick={handleSelectFood}
                    className="cursor-pointer px-2.5 py-1.5 max-w-36 flex justify-center items-center space-x-2 bg-[#ff1616] rounded-lg shadow sm:mx-2 text-white"
                  >
                    <AddIcon c="#fff" w="15" h="15" />
                    <span>Add to cart</span>
                  </div>
                </div>
              </div>

              <div className="relative">
                <ul className="h-auto max-h-48 overflow-y-auto flex flex-wrap p-2.5 mt-4 gap-2 rounded-lg border border-gray-300">
                  {selectedFoods.map((food, index) => (
                    <li
                      key={index}
                      className="group p-2 border border-gray-300 rounded-lg flex justify-between items-center space-x-2.5 w-68"
                    >
                      <img
                        src={food.Image}
                        alt={food.Product}
                        className="object-cover w-16 h-16 rounded-lg"
                      />
                      <div className="w-40 truncate">
                        <p>{food.Product}</p>
                        <p className="text-gray-500 text-xs truncate w-28">
                          {food.Description}
                        </p>
                        <div className="flex justify-between items-center">
                          {food.Discounted == "" || food.Discounted == "0" ? (
                            <p className="text-red-500 text-xs">
                              &#8369;
                              {Math.round(
                                parseInt(food.Price) * markdown +
                                  parseInt(food.Price)
                              )}
                            </p>
                          ) : (
                            <div className="flex justify-start items-center space-x-2.5">
                              <p className="text-gray-300 text-xs">
                                &#8369;
                                {Math.round(
                                  parseInt(food.Price) * markdown +
                                    parseInt(food.Price)
                                )}
                              </p>
                              <p className="text-red-500 text-xs">
                                &#8369;
                                {Math.round(
                                  parseInt(food.Discounted) * markdown +
                                    parseInt(food.Discounted)
                                )}
                              </p>
                            </div>
                          )}
                        </div>
                      </div>
                      {!lockPay && (
                        <button
                          type="button"
                          onClick={() => handleRemoveFood(index)}
                          className="hidden group-hover:inline-flex cursor-pointer flex justify-center items-center bg-slate-200 h-6 w-6 rounded-full"
                        >
                          <CloseIcon c="#404040" w="16" h="16" />
                        </button>
                      )}
                    </li>
                  ))}

                  {selectedFoods.length === 0 && (
                    <div className="text-center flex justify-center items-center w-full">
                      <p className="p-4 text-xl font-medium text-gray-300">
                        Add a product
                      </p>
                    </div>
                  )}
                </ul>
                {lockPay && (
                  <div className="hover:hidden border border-gray-300 rounded-lg flex justify-center items-center bg-white bg-opacity-90 inset-0 absolute top-0 right-0 bottom-0 left-0">
                    <p className="text-xl font-medium text-gray-400">
                      Product already processed
                    </p>
                  </div>
                )}

                {selectedFoods.length !== 0 && !lockPay && (
                  <div>
                    <button
                      className="my-2 w-56 rounded-md bg-red-600 px-3 py-2.5 text-lg text-white shadow-sm hover:bg-[#ff1616] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-600"
                      onClick={commRATE}
                      type="button"
                    >
                      Add to Unit Price
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-6 flex items-center justify-end gap-x-6">
        {loading ? (
          <LoadingButton />
        ) : (
          uploadProgress === 0 && (
            <button
              type="submit"
              className="w-56 rounded-md bg-red-600 px-3 py-2.5 text-lg text-white shadow-sm hover:bg-[#ff1616] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-600"
            >
              {HereMerchant.length !== 0 ? "Update Payment" : "Create Payment"}
            </button>
          )
        )}
      </div>
      <Toast2 visible={errorShow} message={errormsg} />
    </form>
  );
};

function PaymentPage({ storedUser, setSideMenuOpen, activeSideMenu }) {
  const [activeScreen, setAScreen] = useState("TABLE"); // Default screen
  const [showMod, showModaal] = useState(false);

  const showCalendar = () => {
    showModaal(true);
  };

  const changeView = (screen) => {
    setAScreen(screen);
  };

  const back2Merchant = () => {
    setAScreen("TABLE");
    setManage(null);
  };

  const [HereMerchant, setManage] = useState(null);
  const ManageStore = (it) => {
    setAScreen("CREATE");
    setManage(it);
  };

  const [openData, setOpenData] = useState([]);
  const openStore = (store) => {
    setAScreen("LOAD");
    setOpenData(store);
  };

  const [StoreProduct, SetStoreProduct] = useState([]);
  const [editProduct, setEditProduct] = useState([]);

  const AddProduct = () => {
    setEditProduct([]);
    setAScreen("ADD");
  };

  const EditNga = () => {
    setAScreen("ADD");
  };

  const renderScreen = () => {
    switch (activeScreen) {
      case "CREATE":
        return (
          <CreateMerchant HereMerchant={HereMerchant} storedUser={storedUser} />
        );
      default:
        return <LoadPartners openStore={openStore} ManageStore={ManageStore} />;
    }
  };

  return (
    <div className="bg-white">
      <nav className="block lg:hidden bg-red-500 top-2 h-14 shadow-xl w-full">
        <button
          onClick={() => setSideMenuOpen(!activeSideMenu)}
          className="block lg:hidden absolute top-2.5 left-2 bg-white p-2 rounded-lg shadow-xl"
        >
          <BurgerIcon c="#dc2626" w={20} h={20} />
        </button>
      </nav>
      <div className="p-4">
        {/* for mobile view */}
        <div className="flex justify-between items-center  sm:hidden">
          <div>
            {activeScreen !== "CREATE" && (
              <Button1 click={showCalendar} text="Generate Report" />
            )}
          </div>

          <div className="block sm:hidden"></div>

          <div>
            {activeScreen === "CREATE" ? (
              <Button1 click={back2Merchant} text="Back to Payments" />
            ) : (
              <>
                {activeScreen === "LOAD" ? (
                  <ButtonAdd text="Add Product" click={AddProduct} />
                ) : activeScreen === "ADD" ? (
                  <Button1 click={() => openStore(openData)} text="Close" />
                ) : (
                  <ButtonAdd
                    click={() => changeView("CREATE")}
                    text="Create Payment"
                  />
                )}
              </>
            )}
          </div>
        </div>
        <div className="flex justify-between items-center">
          <div className="flex justify-start space-x-2.5 items-center">
            {activeScreen === "LOAD" && (
              <div onClick={back2Merchant} className="cursor-pointer">
                <ArrowLeftBig c="#404040" h="20" w="20" />
              </div>
            )}
            <BigGreetingsTitle
              text={
                activeScreen === "LOAD"
                  ? openData.StoreName
                  : activeScreen === "ADD"
                  ? "Add Product"
                  : "Payments"
              }
            />
            <div className="cursor-pointer bg-gray-300 w-px h-8"></div>
            <div className="hidden sm:block">
              {activeScreen !== "CREATE" && (
                <Button1 click={showCalendar} text="Generate Report" />
              )}
            </div>
          </div>
          <div className="hidden sm:flex justify-start items-center space-x-2">
            {activeScreen === "CREATE" ? (
              <Button1 click={back2Merchant} text="Back to Payments" />
            ) : (
              <>
                {activeScreen === "LOAD" ? (
                  <ButtonAdd text="Add Product" click={AddProduct} />
                ) : activeScreen === "ADD" ? (
                  <Button1 click={() => openStore(openData)} text="Close" />
                ) : (
                  <ButtonAdd
                    click={() => changeView("CREATE")}
                    text="Create Payment"
                  />
                )}
              </>
            )}
          </div>
        </div>

        {renderScreen()}
      </div>
      <Modal2 show={showMod} storedUser={storedUser} showModaal={showModaal} />
    </div>
  );
}

export default PaymentPage;
