      Description: formData.productdes,
      Price: formData.price,
      Image: cover,
      Status: formData.status,
      Category: formData.category,
      Promotion: formData.promotion,
      Required: productIDFORM,
      Discount: formData.discounted,
      Inclusion: InclusionIDs.join(", "),
      Optional: RelatedIDs.join(", "),
      Type: formData.type,
      Size1: formData.size1,
      Size2: formData.size2,
      Size3: formData.size3,
