export const Toast1 = (props) =>{
    return (
        <div className={`fixed ${props.visible} bottom-8 flex justify-start lg:justify-center md:justify-center items-center`}>
             <div className="animate-bounce p-4 shadow-xl bg-black text-white w-80 md:w-auto lg:w-auto max-h-96 rounded-xl">
                <p>{props.message}</p>
            </div>
        </div>
    )
}

