import axios from "axios";
import React, { useEffect, useState } from "react";
import {
  Button1,
  ButtonAdd,
  ButtonWithIcon,
  LoadingButton,
} from "../components/button";
import {
  ArrowLeftBig,
  BurgerIcon,
  CloseIcon,
  ImageIcon,
  SettingsIcon,
} from "../components/icons";
import { Loader } from "../components/loader";
import { BigGreetingsTitle } from "../components/title";
import { Toast2 } from "../components/toast";

const LoadPartners = ({ ManageStore, openStore }) => {
  // const allpartners = NearbyStore();
  const [allpartners, setPartners] = useState([]);
  useEffect(() => {
    const fetchPartners = async () => {
      try {
        const response = await axios.get(
          "https://kiapifers-dlver.cloud/Advertisement/pullads/",
          {
            access: null,
          }
        );

        const alldata = response.data;

        if (alldata.status) {
          setPartners(alldata.advertisements);
        }
      } catch (e) {
        console.log(e);
      }
    };

    fetchPartners();
  }, [setPartners]);

  return (
    <section className="rounded-t-xl max-h-[85vh] bg-white overflow-x-auto w-full">
      <table className="rounded-t-xl table-auto border-collapse whitespace-nowrap w-full">
        <thead className="sticky top-0 bg-[#ff1616] p-4 rounded-t-xl border dark:border-gray-700 relative w-full">
          <tr className="leading-none  z-50 snap-center p-4">
            <th className="text-white text-center relative p-2.5 font-normal">
              Ads Image
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Description
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Expiration
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Status
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Ads License
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Placement
            </th>
            <th className="text-white text-center relative py-2.5 px-6 font-normal">
              Manage
            </th>
          </tr>
        </thead>
        <tbody className="bg-white">
          {allpartners.map((store) => (
            <tr
              onClick={() => ManageStore(store)}
              className="hover:bg-red-50 border border-gray-300 "
              key={store.AdsID}
            >
              <td className="w-48  flex justify-center items-center p-2">
                <img
                  src={store.Image}
                  alt={store.AdsID}
                  className="transform hover:scale-150 w-auto h-16 rounded-xl object-cover"
                />
              </td>
              <td className="text-center ">
                <p className="w-48 truncate">{store.Description}</p>
              </td>

              <td className="text-left">
                <div className="flex justify-center items-center">
                  <div className="text-center px-2.5 h-10 w-10 flex justify-center items-center rounded-full bg-slate-100">
                    <p className="text-sm">{store.Expiration}</p>
                  </div>
                </div>
              </td>

              <td className="text-center">
                <div
                  className={`${
                    store.Status === "Active"
                      ? "bg-green-500 text-white"
                      : "bg-slate-200 text-gray-600"
                  } px-2 py-0.5 mx-2.5 rounded-lg`}
                >
                  {store.Status}
                </div>
              </td>

              <td className="text-center font-mono">{store.AdsID}</td>

              <td className="text-center">
                <div className="flex justify-center items-center">
                  <div className="w-16 bg-slate-200 text-gray-600 px-2 py-0.5 rounded-lg ">
                    {store.Placement}
                  </div>
                </div>
              </td>

              <td className="text-center">
                <div className="px-2.5">
                  <ButtonWithIcon
                    press={() => ManageStore(store)}
                    children={<SettingsIcon c="#dc2626" w="18" h="18" />}
                    title="Manage Ads"
                  />
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {allpartners.length === 0 && (
        <div className="h-96 flex justify-center items-center p-8">
          <Loader />
        </div>
      )}
    </section>
  );
};

const CreateMerchant = ({ HereMerchant, openData, storedUser }) => {
  const [errormsg, setError] = useState("Oops!");
  const [errorShow, setShow] = useState("hidden");
  const showAlert = (msg) => {
    setError(msg);
    setShow("");
    setTimeout(() => {
      setShow("hidden");
    }, 5000);
  };

  if (HereMerchant === null) {
    var HereMerchant = [];
  }

  const [formData, setFormData] = useState({
    about: HereMerchant.Description || "",
    file: HereMerchant.Image || null,
    adsid: HereMerchant.AdsID || "",
    status: HereMerchant.Status || "Inactive",
    placement: HereMerchant.Placement || "P1",
    expire: HereMerchant.Expiration || "1D",
    merchant: HereMerchant.Link || "",
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData({
      ...formData,
      [name]: type === "checkbox" ? checked : value,
    });
  };

  const ResetNga = () => {
    setFormData({
      about: HereMerchant.Description || "",
      file: HereMerchant.Image || null,
      adsid: HereMerchant.AdsID || "",
      status: HereMerchant.Status || "Inactive",
      placement: HereMerchant.Placement || "P1",
      expire: HereMerchant.Expiration || "1D",
      merchant: HereMerchant.Link || "",
    });
    setCover(null);
    setUploadProgress(0);
  };

  //====UPLOADING FILE
  const [cover, setCover] = useState(HereMerchant.Image || null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const handleFileChange = (e) => {
    const file = e.target.files[0];

    setFormData({
      ...formData,
      file: file,
    });
    setCover(URL.createObjectURL(file));
    UploadImage(file);
  };

  const UploadImage = async (file) => {
    const data = new FormData();
    data.append("file", file);

    try {
      const response = await axios.post(
        "https://kiapifers-dlver.cloud/storage/",
        data,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
          onUploadProgress: (progressEvent) => {
            const percentCompleted = Math.round(
              (progressEvent.loaded * 100) / progressEvent.total
            );
            setUploadProgress(percentCompleted);
          },
        }
      );

      if (response.data.success) {
        setUploadProgress(0); // Reset progress after success
        setCover(response.data.url);
      } else {
        showAlert("Error: " + response.data.error);
        setUploadProgress(0); // Reset progress after error
        setCover(null);
      }
    } catch (error) {
      console.error("There was an error uploading the file!", error);
      setUploadProgress(0); // Reset progress after error
      setCover(null);
    }
  };

  const resetImage = () => {
    setCover(null);
  };

  const validate = () => {
    const newErrors = {};

    if (!formData.about) newErrors.about = "Description is required";
    if (!formData.expire) newErrors.expire = "Expiration is required";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const [loading, setLoading] = useState(false);
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    const data = new FormData();
    for (const key in formData) {
      data.append(key, formData[key]);
    }

    if (!cover) {
      showAlert("Image is required");
      return;
    }

    try {
      setLoading(true);

      var boday = {
        Email: storedUser.email,
        Image: cover,
        Description: formData.about,
        Expiration: formData.expire,
        Status: formData.status,
        Placement: formData.placement,
        AdsID: formData.adsid,
        Merchant: formData.merchant,
      };
      var api = "https://kiapifers-dlver.cloud/Advertisement/updateads/";
      if (HereMerchant === null || HereMerchant.length === 0) {
        api = "https://kiapifers-dlver.cloud/Advertisement/createads/";
        boday = {
          Email: storedUser.email,
          Image: cover,
          Description: formData.about,
          Expiration: formData.expire,
          Status: formData.status,
          Placement: formData.placement,
          Merchant: formData.merchant,
        };
      }

      const response = await axios.post(api, boday, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      console.log(response.data);
      setLoading(false);
      ResetNga();
      showAlert(
        HereMerchant === null || HereMerchant.length === 0
          ? "Successfully Added!"
          : "Updated!"
      );
    } catch (error) {
      console.error(error);
      showAlert("Please try again. Error!");
      setLoading(false);
    }
  };

  return (
    <form className="px-2.5" onSubmit={handleSubmit}>
      <div className="space-y-12">
        <div className="border-b border-gray-900/10 pb-12">
          <h2 className="text-base font-semibold leading-7 text-gray-900">
            Ads Information
          </h2>
          <p className="mt-1 text-sm leading-6 text-gray-600">
            This information will be displayed publicly so be careful what you
            inputs,{" "}
            <span className="text-red-500 font-medium">ask for a review</span>.
          </p>

          <div className="mt-10 grid grid-cols-1 gap-x-6 gap-y-8 sm:grid-cols-6">
            <div className="sm:col-span-2">
              <label
                htmlFor="file-upload"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Ads photo
              </label>
              {cover ? (
                <div>
                  <div className="border border-gray-300 rounded-lg w-[312px] relative">
                    <img
                      src={cover}
                      alt="loading"
                      style={{ width: "312px", height: "512px" }}
                      className="object-cover rounded-lg"
                    />
                    <div
                      onClick={resetImage}
                      className="rounded-full shadow-xl cursor-pointer transform scale-100 hover:scale-150 bg-white border border-gray-300 absolute -top-2 -right-2"
                    >
                      <CloseIcon c="#404040" w="20" h="20" />
                    </div>

                    {uploadProgress > 0 && (
                      <div className="flex justify-center items-center inset-0 absolute rounded-lg bg-white bg-opacity-50  w-full h-full">
                        <div>
                          <div className="text-gray-800">
                            Uploading: {uploadProgress}%
                          </div>
                          <div
                            style={{ width: "100%", backgroundColor: "#fff" }}
                          >
                            <div
                              style={{
                                width: `${uploadProgress}%`,
                                backgroundColor: "#ef4444",
                                height: "10px",
                              }}
                            ></div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ) : (
                <div className="mt-2 flex justify-center items-center w-[312px]  h-[412px] rounded-lg border border-dashed border-gray-900/25 px-6 py-10">
                  <div className="text-center">
                    <div className="flex justify-center items-center w-full">
                      <ImageIcon c="#404040" w={20} h={20} />
                    </div>
                    <div className="mt-4 flex text-sm leading-6 text-gray-600">
                      <label
                        htmlFor="file-upload"
                        className="relative cursor-pointer rounded-md bg-white font-semibold text-yellow-600  hover:text-red-500"
                      >
                        <span>Upload a file</span>
                        <input
                          id="file-upload"
                          name="file-upload"
                          type="file"
                          className="sr-only outline-none cursor-pointer"
                          onChange={handleFileChange}
                        />
                      </label>
                      <p className="pl-1">or drag and drop</p>
                    </div>
                    <p className="text-xs leading-5 text-gray-600">
                      PNG, JPG up to 5MB and must be 312 x 412
                    </p>
                  </div>
                </div>
              )}
            </div>

            <div className="sm:col-span-3">
              <label
                htmlFor="about"
                className="block text-sm font-medium leading-6 text-gray-900"
              >
                Description
              </label>
              <div className="mt-2">
                <textarea
                  id="about"
                  name="about"
                  rows={1}
                  maxLength={100}
                  className="block w-full rounded-md border-0 py-1.5 px-2.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 outline-none sm:text-sm sm:leading-6"
                  value={formData.about}
                  onChange={handleChange}
                />
              </div>
              {errors.about && (
                <p className="text-red-500 text-sm">{errors.about}</p>
              )}
              <p className="mt-3 text-sm leading-6 text-gray-600">
                Write a few sentences about this ads.
              </p>

              <div className="mt-4">
                <label
                  htmlFor="merchant"
                  className="block text-sm font-medium  leading-6 text-gray-900"
                >
                  Merchant ID
                </label>
                <div className="mt-2">
                  <input
                    id="merchant"
                    name="merchant"
                    type="text"
                    placeholder="e.g A0TYASNK"
                    maxLength={100}
                    className="block w-full font-mono font-medium rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                    value={formData.merchant}
                    onChange={handleChange}
                  />
                </div>
                {errors.merchant && (
                  <p className="text-red-500 text-sm">{errors.merchant}</p>
                )}
              </div>

              <div className="mt-4 hidden">
                <label
                  htmlFor="adsid"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Ads Licence
                </label>
                <div className="mt-2">
                  <input
                    id="adsid"
                    name="adsid"
                    type="text"
                    className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 px-2.5 outline-none sm:text-sm sm:leading-6"
                    value={formData.adsid}
                    onChange={handleChange}
                    readOnly={HereMerchant === null ? true : false}
                  />
                </div>
                {errors.adsid && (
                  <p className="text-red-500 text-sm">{errors.adsid}</p>
                )}
              </div>

              <div className="mt-4">
                <label
                  htmlFor="status"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Status
                </label>
                <div className="mt-2">
                  <select
                    id="status"
                    name="status"
                    className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                    value={formData.status}
                    onChange={handleChange}
                  >
                    <option value="Inactive">Inactive</option>
                    <option value="Active">Active</option>
                  </select>
                </div>
              </div>

              <div className="mt-4">
                <label
                  htmlFor="expire"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Expiration
                </label>
                <div className="mt-2">
                  <select
                    id="expire"
                    name="expire"
                    className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                    onChange={handleChange}
                    value={formData.expire}
                  >
                    <option value="1D">1 day</option>
                    <option value="4D">4 days</option>
                    <option value="6D">6 days</option>
                    <option value="1W">1 week</option>
                    <option value="2W">2 weeks</option>
                  </select>
                </div>
              </div>

              <div className="mt-4">
                <label
                  htmlFor="placement"
                  className="block text-sm font-medium leading-6 text-gray-900"
                >
                  Position
                </label>
                <div className="mt-2">
                  <select
                    id="placement"
                    name="placement"
                    className="block w-full rounded-md border-0 py-1.5 text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 px-2 outline-none sm:max-w-xs sm:text-sm sm:leading-6"
                    onChange={handleChange}
                    value={formData.placement}
                  >
                    <option value="P1">Placement 1</option>
                    <option value="P2">Placement 2</option>
                    <option value="P3">Placement 3</option>
                  </select>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-6 flex items-center justify-end gap-x-6">
        {loading ? (
          <LoadingButton />
        ) : (
          uploadProgress === 0 && (
            <button
              type="submit"
              className="w-56 rounded-md bg-red-600 px-3 py-2.5 text-lg text-white shadow-sm hover:bg-[#ff1616] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-600"
            >
              {HereMerchant.length !== 0 ? "Update Ads" : "Create Ads"}
            </button>
          )
        )}
      </div>
      <Toast2 visible={errorShow} message={errormsg} />
    </form>
  );
};

function AdsPage({ storedUser, setSideMenuOpen, activeSideMenu }) {
  const [activeScreen, setAScreen] = useState("TABLE"); // Default screen

  const changeView = (screen) => {
    setAScreen(screen);
  };

  const back2Merchant = () => {
    setAScreen("TABLE");
    setManage(null);
  };

  const [HereMerchant, setManage] = useState(null);
  const ManageStore = (it) => {
    setAScreen("CREATE");
    setManage(it);
  };

  const [openData, setOpenData] = useState([]);
  const openStore = (store) => {
    setAScreen("LOAD");
    setOpenData(store);
  };

  const [StoreProduct, SetStoreProduct] = useState([]);
  const [editProduct, setEditProduct] = useState([]);

  const AddProduct = () => {
    setEditProduct([]);
    setAScreen("ADD");
  };

  const EditNga = () => {
    setAScreen("ADD");
  };

  const renderScreen = () => {
    switch (activeScreen) {
      case "CREATE":
        return (
          <CreateMerchant storedUser={storedUser} HereMerchant={HereMerchant} />
        );
      default:
        return <LoadPartners openStore={openStore} ManageStore={ManageStore} />;
    }
  };

  return (
    <div className="bg-white">
      <nav className="block  lg:hidden bg-red-500 top-2 h-14 shadow-xl w-full">
        <button
          onClick={() => setSideMenuOpen(!activeSideMenu)}
          className="block lg:hidden absolute top-2.5 left-2 bg-white p-2 rounded-lg shadow-xl"
        >
          <BurgerIcon c="#dc2626" w={20} h={20} />
        </button>
      </nav>
      <div className="p-4">
        <div className="flex justify-between items-center">
          <div className="flex justify-start space-x-2.5 items-center">
            {activeScreen === "LOAD" && (
              <div onClick={back2Merchant} className="cursor-pointer">
                <ArrowLeftBig c="#404040" h="20" w="20" />
              </div>
            )}
            <BigGreetingsTitle
              text={
                activeScreen === "LOAD"
                  ? openData.StoreName
                  : activeScreen === "ADD"
                  ? "Add Product"
                  : "Mobile Ads"
              }
            />
            <div className="cursor-pointer bg-gray-300 w-px h-8"></div>
          </div>
          <div className="flex justify-start items-center space-x-2">
            {activeScreen === "CREATE" ? (
              <Button1 click={back2Merchant} text="Back to Ads" />
            ) : (
              <>
                {activeScreen === "LOAD" ? (
                  <ButtonAdd text="Add Product" click={AddProduct} />
                ) : activeScreen === "ADD" ? (
                  <Button1 click={() => openStore(openData)} text="Close" />
                ) : (
                  <ButtonAdd
                    click={() => changeView("CREATE")}
                    text="Create Ads"
                  />
                )}
              </>
            )}
          </div>
        </div>

        {renderScreen()}
      </div>
    </div>
  );
}

export default AdsPage;
