import React, { useState } from "react";
import { EyeClose, EyeOpen, SearchIcon } from "./icons";

export const EmailTextbox = ({ fun, ...props }) => {
  return (
    <div className="bg-slate-200 p-2.5 rounded-md w-full my-4">
      <input
        type="email"
        onChange={fun}
        placeholder="Enter email"
        value={props.value}
        className="w-full px-2.5 placeholder-slate-500 text-lg bg-transparent outline-none"
      ></input>
    </div>
  );
};

export const PasswordTextbox = ({ fun, value, handleKeyDown }) => {
  const [boxtype, setBoxType] = useState("password");

  const changeBoxMode = () => {
    if (boxtype === "password") {
      setBoxType("text");
    } else {
      setBoxType("password");
    }
  };

  return (
    <div className="bg-slate-200 p-2.5 rounded-md w-full my-4 flex justify-between items-center">
      <input
        onKeyDown={handleKeyDown}
        type={boxtype}
        placeholder="Password"
        onChange={fun}
        value={value}
        className="w-full px-2.5 placeholder-slate-500 text-lg bg-transparent outline-none"
      ></input>
      <div onClick={changeBoxMode} className="cursor-pointer">
        {boxtype === "password" ? (
          <EyeClose c="#64748b" w="20" h="20" />
        ) : (
          <EyeOpen c="#64748b" w="20" h="20" />
        )}
      </div>
    </div>
  );
};

export const CodeTextbox = () => {
  return (
    <div className="bg-slate-200 p-4 rounded-md w-full my-4">
      <input
        type="number"
        placeholder=""
        className="px-2.5 placeholder-slate-500 w-full text-xl font-medium text-center text-2xl text-red-500 bg-transparent outline-none"
      ></input>
    </div>
  );
};

export const ChatTextbox = () => {
  return (
    <div className="bg-white p-4 rounded-xl w-full my-4">
      <textarea
        style={{ resize: "none" }}
        rows={1}
        placeholder="Enter your message"
        className="px-2.5 placeholder-slate-500 text-lg bg-transparent outline-none w-full"
      ></textarea>
    </div>
  );
};

export const SearchTextInput = () => {
  return (
    <div className="bg-slate-200 p-2.5 rounded-2xl w-full flex justify-start items-center">
      <SearchIcon c="#94a3b8" w="23" h="23" />
      <input
        type="text"
        placeholder="Search foods or restaurants"
        className="px-2.5 placeholder-slate-400 text-lg bg-transparent outline-none w-full"
      ></input>
    </div>
  );
};
