import React, { useState } from "react";
import { Triangle } from "./icons";

export const Tooltip = ({ text, children }) => {
  const [showTooltip, setShowTooltip] = useState(false);

  const handleMouseEnter = () => {
    setShowTooltip(true);
  };

  const handleMouseLeave = () => {
    setShowTooltip(false);
  };

  return (
    <div
      className="w-auto"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      {children}
      {showTooltip && (
        <div className="shadow-xl min-w-48 max-w-80 rounded-xl absolute z-50 left-[250px] bottom-[45px] transform -translate-x-1/2 -translate-y-full bg-black text-white text-sm px-2 py-4">
          <div className="flex justify-center items-center">
            <img
              src="https://kiefers-app.com/assets/jc.svg"
              className="h-12 w-12 border-2 border-red-400 rounded-full"
              alt=""
            />
            <p className="px-2 ">{text}</p>
          </div>
          <div className="z-30 absolute -left-2 bottom-3 -rotate-90">
            <Triangle c="#000" w="20" h="20" />
          </div>
        </div>
      )}
    </div>
  );
};

