import React from "react";
import { useNavigate } from "react-router-dom";

function LogoutPage({ onLogout }) {
  const navigate = useNavigate();
  localStorage.removeItem("token");
  localStorage.removeItem("user");

  onLogout();
  navigate("/login");

  return (
    <div>
      <p>Logging out..</p>
    </div>
  );
}

export default LogoutPage;
